#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

/// Returns the size of the terminal attached to stdout, if any.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of(std::io::stdout())
}

pub fn terminal_size_of<F: std::os::fd::AsFd>(f: F) -> Option<(Width, Height)> {
    use std::os::fd::AsRawFd;
    let fd = f.as_fd().as_raw_fd();
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == -1 {
            return None;
        }
        if ws.ws_col == 0 || ws.ws_row == 0 {
            return None;
        }
        Some((Width(ws.ws_col), Height(ws.ws_row)))
    }
}
