impl FromStr for StyleComponentList {
    type Err = Error;

    fn from_str(s: &str) -> Result<Self> {
        let mut list = Vec::new();
        for part in s.split(',') {
            let (modifier, name) = if let Some(rest) = part.strip_prefix('+') {
                (StyleModifier::Add, rest)
            } else if let Some(rest) = part.strip_prefix('-') {
                (StyleModifier::Remove, rest)
            } else {
