use crate::error::*;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LineRange {
    lower: usize,
    upper: usize,
}

impl Default for LineRange {
    fn default() -> LineRange {
        LineRange { lower: usize::MIN, upper: usize::MAX }
    }
}

impl LineRange {
    pub fn new(from: usize, to: usize) -> Self {
        LineRange { lower: from, upper: to }
    }

    pub fn from(range_raw: &str) -> Result<LineRange> {
        LineRange::parse_range(range_raw)
    }

    fn parse_range(range_raw: &str) -> Result<LineRange> {
        let mut new_range = LineRange::default();

        if range_raw.is_empty() {
            return Err(Error::EmptyLineRange);
        }

        if range_raw.bytes().next().ok_or(Error::EmptyLineRange)? == b':' {
            new_range.upper = range_raw[1..].parse()?;
            return Ok(new_range);
        } else if range_raw.bytes().last().ok_or(Error::EmptyLineRange)? == b':' {
            new_range.lower = range_raw[..range_raw.len() - 1].parse()?;
            return Ok(new_range);
        }

        let line_numbers: Vec<&str> = range_raw.split(':').collect();
        match line_numbers.len() {
            1 => {
                new_range.lower = line_numbers[0].parse()?;
                new_range.upper = new_range.lower;
                Ok(new_range)
            }
            2 => {
                new_range.lower = line_numbers[0].parse()?;
                let first_byte = line_numbers[1].bytes().next();

                new_range.upper = if first_byte == Some(b'+') {
                    let more_lines = &line_numbers[1][1..]
                        .parse()
                        .map_err(|_| "Invalid character after +")?;
                    new_range.lower.saturating_add(*more_lines)
                } else if first_byte == Some(b'-') {
                    // this will fail if the number after - is zero
                    new_range.lower = line_numbers[1][1..]
                        .parse::<usize>()
                        .map_err(|_| "Invalid character after -")?
                        .checked_sub(1)
                        .ok_or("Cannot subtract 1 from 0")?;
                    // Hack: the real parse semantics
                    new_range.lower
                } else {
                    line_numbers[1].parse()?
                };

                Ok(new_range)
            }
            3 => {
                let context: usize = line_numbers[2].parse()?;
                if line_numbers[1].is_empty() {
                    let center: usize = line_numbers[0].parse()?;
                    new_range.lower = center.saturating_sub(context);
                    new_range.upper = center.saturating_add(context);
                } else {
                    new_range.lower = line_numbers[0].parse::<usize>()?.saturating_sub(context);
                    new_range.upper = line_numbers[1].parse::<usize>()?.saturating_add(context);
                }
                Ok(new_range)
            }
            _ => Err(
                "Line range contained too many ':' characters. Expected format: 'N', 'N:M', 'N::C', or 'N:M:C'"
                    .into(),
            ),
        }
    }

    pub fn is_inside(&self, line: usize) -> bool {
        line >= self.lower && line <= self.upper
    }

    pub fn lower(&self) -> usize {
        self.lower
    }
    pub fn upper(&self) -> usize {
        self.upper
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RangeCheckResult {
    // Within one of the given ranges
    InRange,

    // Not in any of the given ranges, but there is at least one range with a higher lower bound
    BeforeOrBetweenRanges,

    // Greater than the highest upper bound of all ranges
    AfterLastRange,
}

#[derive(Debug, Clone)]
pub struct LineRanges {
    ranges: Vec<LineRange>,
    largest_upper_bound: usize,
}

impl LineRanges {
    pub fn none() -> LineRanges {
        LineRanges::from(vec![])
    }

    pub fn all() -> LineRanges {
        LineRanges::from(vec![LineRange::default()])
    }

    pub fn from(ranges: Vec<LineRange>) -> LineRanges {
        let largest_upper_bound = ranges.iter().map(|r| r.upper).max().unwrap_or(usize::MAX);
        LineRanges { ranges, largest_upper_bound }
    }

    pub fn check(&self, line: usize) -> RangeCheckResult {
        if self.ranges.iter().any(|r| r.is_inside(line)) {
            RangeCheckResult::InRange
        } else if line < self.largest_upper_bound {
            RangeCheckResult::BeforeOrBetweenRanges
        } else {
            RangeCheckResult::AfterLastRange
        }
    }

    pub fn ranges(&self) -> &[LineRange] {
        &self.ranges
    }
}

impl Default for LineRanges {
    fn default() -> Self {
        Self::all()
    }
}

#[derive(Debug, Clone, Default)]
pub struct HighlightedLineRanges(pub LineRanges);

impl Default for HighlightedLineRangesHelper {
    fn default() -> Self {
        HighlightedLineRangesHelper
    }
}
pub struct HighlightedLineRangesHelper;

pub fn parse_highlighted_default() -> HighlightedLineRanges {
    HighlightedLineRanges(LineRanges::none())
}
