//! ANSI terminal styling helpers.

use std::fmt::Write as _;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Color {
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Purple,
    Cyan,
    White,
    Fixed(u8),
    Rgb(u8, u8, u8),
}

impl Color {
    fn write_fg(&self, out: &mut String) {
        match self {
            Color::Black => out.push_str("30"),
            Color::Red => out.push_str("31"),
            Color::Green => out.push_str("32"),
            Color::Yellow => out.push_str("33"),
            Color::Blue => out.push_str("34"),
            Color::Purple => out.push_str("35"),
            Color::Cyan => out.push_str("36"),
            Color::White => out.push_str("37"),
            Color::Fixed(n) => {
                let _ = write!(out, "38;5;{}", n);
            }
            Color::Rgb(r, g, b) => {
                let _ = write!(out, "38;2;{};{};{}", r, g, b);
            }
        }
    }
    fn write_bg(&self, out: &mut String) {
        match self {
            Color::Black => out.push_str("40"),
            Color::Red => out.push_str("41"),
            Color::Green => out.push_str("42"),
            Color::Yellow => out.push_str("43"),
            Color::Blue => out.push_str("44"),
            Color::Purple => out.push_str("45"),
            Color::Cyan => out.push_str("46"),
            Color::White => out.push_str("47"),
            Color::Fixed(n) => {
                let _ = write!(out, "48;5;{}", n);
            }
            Color::Rgb(r, g, b) => {
                let _ = write!(out, "48;2;{};{};{}", r, g, b);
            }
        }
    }
    pub fn normal(self) -> Style {
        Style {
            foreground: Some(self),
            ..Style::default()
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Style {
    pub foreground: Option<Color>,
    pub background: Option<Color>,
    pub is_bold: bool,
    pub is_dimmed: bool,
    pub is_italic: bool,
    pub is_underline: bool,
}

impl Style {
    pub fn new() -> Style {
        Style::default()
    }
    pub fn bold(mut self) -> Style {
        self.is_bold = true;
        self
    }
    pub fn italic(mut self) -> Style {
        self.is_italic = true;
        self
    }
    pub fn underline(mut self) -> Style {
        self.is_underline = true;
        self
    }
    pub fn fg(mut self, c: Color) -> Style {
        self.foreground = Some(c);
        self
    }
    pub fn on(mut self, c: Color) -> Style {
        self.background = Some(c);
        self
    }
    pub fn is_plain(&self) -> bool {
        *self == Style::default()
    }

    pub fn prefix(&self) -> String {
        if self.is_plain() {
            return String::new();
        }
        let mut out = String::from("\x1b[");
        let mut written = false;
        let mut sep = |out: &mut String| {
            if written {
                out.push(';');
            }
            written = true;
        };
        if self.is_bold {
            sep(&mut out);
            out.push('1');
        }
        if self.is_dimmed {
            sep(&mut out);
            out.push('2');
        }
        if self.is_italic {
            sep(&mut out);
            out.push('3');
        }
        if self.is_underline {
            sep(&mut out);
            out.push('4');
        }
        if let Some(bg) = self.background {
            sep(&mut out);
            bg.write_bg(&mut out);
        }
        if let Some(fg) = self.foreground {
            sep(&mut out);
            fg.write_fg(&mut out);
        }
        out.push('m');
        out
    }

    pub fn paint(&self, text: &str) -> String {
        if self.is_plain() {
            return text.to_string();
        }
        let mut s = self.prefix();
        s.push_str(text);
        s.push_str("\x1b[0m");
        s
    }
}

/// Convert an 8-bit sRGB colour into the closest colour of the 256-colour ANSI palette.
pub fn ansi256_from_rgb(r: u8, g: u8, b: u8) -> u8 {
    crate::ansi_colours::ansi256_from_rgb(r, g, b)
}

/// A theme colour: RGB plus alpha byte used for special encodings.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ThemeColor {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub a: u8,
}

impl ThemeColor {
    pub const fn rgb(r: u8, g: u8, b: u8) -> ThemeColor {
        ThemeColor { r, g, b, a: 0xff }
    }
    pub const fn rgba(r: u8, g: u8, b: u8, a: u8) -> ThemeColor {
        ThemeColor { r, g, b, a }
    }
}

pub fn to_ansi_color(color: ThemeColor, true_color: bool) -> Option<Color> {
    if color.a == 0 {
        Some(match color.r {
            0x00 => Color::Black,
            0x01 => Color::Red,
            0x02 => Color::Green,
            0x03 => Color::Yellow,
            0x04 => Color::Blue,
            0x05 => Color::Purple,
            0x06 => Color::Cyan,
            0x07 => Color::White,
            n => Color::Fixed(n),
        })
    } else if color.a == 1 {
        None
    } else if true_color {
        Some(Color::Rgb(color.r, color.g, color.b))
    } else {
        Some(Color::Fixed(ansi256_from_rgb(color.r, color.g, color.b)))
    }
}

pub const FONT_BOLD: u8 = 1;
pub const FONT_UNDERLINE: u8 = 2;
pub const FONT_ITALIC: u8 = 4;

/// Style of a highlighted region.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HlStyle {
    pub foreground: ThemeColor,
    pub background: ThemeColor,
    pub font_style: u8,
}

pub fn as_terminal_escaped(
    style: HlStyle,
    text: &str,
    true_color: bool,
    colored: bool,
    italics: bool,
    background_color: Option<ThemeColor>,
) -> String {
    if text.is_empty() {
        return String::new();
    }
    let mut st = if !colored {
        Style::default()
    } else {
        let color = to_ansi_color(style.foreground, true_color);
        let mut s = Style {
            foreground: color,
            ..Style::default()
        };
        if style.font_style & FONT_BOLD != 0 {
            s.is_bold = true;
        } else if style.font_style & FONT_UNDERLINE != 0 {
            s.is_underline = true;
        } else if italics && style.font_style & FONT_ITALIC != 0 {
            s.is_italic = true;
        }
        s
    };
    st.background = background_color.and_then(|c| to_ansi_color(c, true_color));
    st.paint(text)
}
