use std::path::Path;

use globset::{Glob, GlobMatcher};

use crate::error::*;

#[derive(Debug, Clone)]
pub enum MappingTarget {
    MapTo(String),
    MapToUnknown,
    MapExtensionToUnknown,
}

#[derive(Debug, Clone)]
pub struct SyntaxMapping {
    mappings: Vec<(GlobMatcher, MappingTarget)>,
    ignored_suffixes: Vec<String>,
}

impl Default for SyntaxMapping {
    fn default() -> Self {
        SyntaxMapping {
            mappings: Vec::new(),
            ignored_suffixes: Vec::new(),
        }
    }
}

impl SyntaxMapping {
    pub fn new() -> SyntaxMapping {
        SyntaxMapping::default()
    }

    pub fn insert(&mut self, from: &str, to: MappingTarget) -> Result<()> {
        let glob = Glob::new(from).map_err(|e| Error::Msg(format!("{}", e)))?;
        self.mappings.push((glob.compile_matcher(), to));
        Ok(())
    }

    pub fn insert_ignored_suffix(&mut self, suffix: &str) {
        self.ignored_suffixes.push(suffix.to_string());
    }

    pub fn ignored_suffixes(&self) -> &[String] {
        &self.ignored_suffixes
    }

    /// Returns the user mapping for the given path (user mappings have highest priority,
    /// later mappings override earlier ones).
    pub fn get_syntax_for(&self, path: &Path) -> Option<&MappingTarget> {
        // Try matching on the file name as-is.
        let candidate = globset::Candidate::new(path);
        let candidate_filename = path.file_name().map(globset::Candidate::new);
        for (glob, syntax) in self.mappings.iter().rev() {
            if glob.is_match_candidate(&candidate)
                || candidate_filename
                    .as_ref()
                    .map_or(false, |filename| glob.is_match_candidate(filename))
            {
                return Some(syntax);
            }
        }
        None
    }
}
