use std::fs::File;
use std::io::{self, BufRead, BufReader, Read};
use std::path::{Path, PathBuf};

use crate::error::*;

#[derive(Debug, Clone)]
pub struct InputDescription {
    pub name: String,
    pub kind: Option<String>,
    pub summary: Option<String>,
}

impl InputDescription {
    pub fn new(name: impl Into<String>) -> Self {
        InputDescription {
            name: name.into(),
            kind: None,
            summary: None,
        }
    }
    pub fn kind(&self) -> Option<&String> {
        self.kind.as_ref()
    }
    pub fn title(&self) -> &str {
        &self.name
    }
    pub fn summary(&self) -> String {
        self.summary.clone().unwrap_or_else(|| match &self.kind {
            Some(kind) => format!("{} '{}'", kind.to_lowercase(), self.name),
            None => self.name.clone(),
        })
    }
}

#[derive(Debug, Clone)]
pub enum InputKind {
    OrdinaryFile(PathBuf),
    StdIn,
    CustomReader,
}

#[derive(Debug, Clone, Default)]
pub struct InputMetadata {
    pub user_provided_name: Option<PathBuf>,
    pub size: Option<u64>,
}

#[derive(Debug, Clone)]
pub struct Input {
    pub kind: InputKind,
    pub metadata: InputMetadata,
    pub description: InputDescription,
}

impl Input {
    pub fn ordinary_file(path: impl AsRef<Path>) -> Self {
        let path = path.as_ref();
        let mut description = InputDescription::new(path.to_string_lossy());
        description.kind = Some("File".to_owned());
        Input {
            kind: InputKind::OrdinaryFile(path.to_path_buf()),
            metadata: InputMetadata::default(),
            description,
        }
    }

    pub fn stdin() -> Self {
        let mut description = InputDescription::new("STDIN");
        description.summary = Some("STDIN".to_owned());
        Input {
            kind: InputKind::StdIn,
            metadata: InputMetadata::default(),
            description,
        }
    }

    pub fn is_stdin(&self) -> bool {
        matches!(self.kind, InputKind::StdIn)
    }

    pub fn with_name(mut self, provided_name: Option<&Path>) -> Self {
        if let Some(name) = provided_name {
            self.description.name = name.to_string_lossy().to_string();
            self.description.kind = Some("File".to_owned());
            self.description.summary = None;
            self.metadata.user_provided_name = Some(name.to_path_buf());
        }
        self
    }

    pub fn path(&self) -> Option<&Path> {
        self.metadata
            .user_provided_name
            .as_deref()
            .or_else(|| match &self.kind {
                InputKind::OrdinaryFile(p) => Some(p.as_path()),
                _ => None,
            })
    }

    pub fn open(&mut self) -> Result<OpenedInput> {
        match &self.kind {
            InputKind::StdIn => {
                let stdin = io::stdin();
                let reader = InputReader::new(Box::new(BufReader::new(stdin)));
                Ok(OpenedInput {
                    kind: OpenedInputKind::StdIn,
                    description: self.description.clone(),
                    metadata: self.metadata.clone(),
                    reader,
                })
            }
            InputKind::OrdinaryFile(path) => {
                let file = File::open(path).map_err(|e| {
                    Error::Msg(format!("'{}': {}", path.to_string_lossy(), e))
                })?;
                let md = file.metadata();
                if let Ok(md) = &md {
                    if md.is_dir() {
                        return Err(Error::Msg(format!(
                            "'{}' is a directory.",
                            path.to_string_lossy()
                        )));
                    }
                    self.metadata.size = Some(md.len());
                }
                let reader = InputReader::new(Box::new(BufReader::new(file)));
                Ok(OpenedInput {
                    kind: OpenedInputKind::OrdinaryFile(path.clone()),
                    description: self.description.clone(),
                    metadata: self.metadata.clone(),
                    reader,
                })
            }
            InputKind::CustomReader => unreachable!(),
        }
    }
}

#[derive(Debug, Clone)]
pub enum OpenedInputKind {
    OrdinaryFile(PathBuf),
    StdIn,
}

pub struct OpenedInput {
    pub kind: OpenedInputKind,
    pub description: InputDescription,
    pub metadata: InputMetadata,
    pub reader: InputReader,
}

impl OpenedInput {
    pub fn path(&self) -> Option<&Path> {
        self.metadata
            .user_provided_name
            .as_deref()
            .or_else(|| match &self.kind {
                OpenedInputKind::OrdinaryFile(p) => Some(p.as_path()),
                _ => None,
            })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ContentType {
    Binary,
    Utf8,
    Utf8Bom,
    Utf16LE,
    Utf16BE,
    Utf32LE,
    Utf32BE,
}

pub fn inspect(buffer: &[u8]) -> ContentType {
    const BOMS: &[(&[u8], ContentType)] = &[
        (&[0xEF, 0xBB, 0xBF], ContentType::Utf8Bom),
        (&[0x00, 0x00, 0xFE, 0xFF], ContentType::Utf32BE),
        (&[0xFF, 0xFE, 0x00, 0x00], ContentType::Utf32LE),
        (&[0xFE, 0xFF], ContentType::Utf16BE),
        (&[0xFF, 0xFE], ContentType::Utf16LE),
    ];
    for (bom, ct) in BOMS {
        if buffer.starts_with(bom) {
            return *ct;
        }
    }
    let scan = &buffer[..buffer.len().min(1024)];
    if scan.contains(&0x00) {
        return ContentType::Binary;
    }
    ContentType::Utf8
}

pub struct InputReader {
    inner: Box<dyn BufRead>,
    pub first_line: Vec<u8>,
    pub content_type: Option<ContentType>,
}

impl InputReader {
    pub fn new(mut reader: Box<dyn BufRead>) -> InputReader {
        let mut first_line = vec![];
        reader.read_until(b'\n', &mut first_line).ok();

        let content_type = if first_line.is_empty() {
            None
        } else {
            Some(inspect(&first_line[..]))
        };

        if content_type == Some(ContentType::Utf16LE) {
            reader.read_until(0x00, &mut first_line).ok();
        }

        InputReader {
            inner: reader,
            first_line,
            content_type,
        }
    }

    pub fn read_line(&mut self, buf: &mut Vec<u8>) -> io::Result<bool> {
        if !self.first_line.is_empty() {
            buf.append(&mut self.first_line);
            return Ok(true);
        }

        let res = self.inner.read_until(b'\n', buf).map(|size| size > 0)?;

        if self.content_type == Some(ContentType::Utf16LE) {
            let _ = self.inner.read_until(0x00, buf);
        }

        Ok(res)
    }

    /// Read everything that is left.
    pub fn read_to_end(&mut self, buf: &mut Vec<u8>) -> io::Result<()> {
        buf.append(&mut self.first_line);
        self.inner.read_to_end(buf)?;
        Ok(())
    }
}
