//! Tracking of ANSI escape sequences in the input so that they can be re-applied after
//! bat's own styling sequences.

use std::fmt::{Display, Formatter};

/// Splits a string into chunks of regular text and escape sequences.
pub struct AnsiCodeIterator<'a> {
    s: &'a str,
    pos: usize,
}

impl<'a> AnsiCodeIterator<'a> {
    pub fn new(s: &'a str) -> Self {
        AnsiCodeIterator { s, pos: 0 }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EscapeKind {
    Text,
    /// An incomplete sequence (end of input reached)
    Incomplete,
    /// ESC followed by a single character
    Fe,
    /// ESC + intermediates (0x20..=0x2F) + final byte
    NF,
    /// Control sequence (ESC [)
    Csi,
    /// Operating system command (ESC ])
    Osc,
}

/// Find the extent of an escape sequence beginning at `start` (which must point at ESC).
/// Returns (end_of_sequence_text, next_text_position, kind).
fn escape_sequence_extent(bytes: &[u8], start: usize) -> (usize, usize, EscapeKind) {
    let len = bytes.len();
    let mut i = start + 1;
    if i >= len {
        return (len, len, EscapeKind::Incomplete);
    }
    match bytes[i] {
        b'[' => {
            i += 1;
            // parameter bytes
            while i < len && (0x30..=0x3F).contains(&bytes[i]) {
                i += 1;
            }
            // intermediate bytes
            while i < len && (0x20..=0x2F).contains(&bytes[i]) {
                i += 1;
            }
            if i < len && (0x40..=0x7E).contains(&bytes[i]) {
                i += 1;
                (i, i, EscapeKind::Csi)
            } else if i < len {
                // Invalid byte terminates the sequence (and is consumed).
                i += 1;
                (i, i, EscapeKind::Csi)
            } else {
                (len, len, EscapeKind::Incomplete)
            }
        }
        b']' => {
            i += 1;
            while i < len {
                if bytes[i] == 0x07 {
                    i += 1;
                    return (i, i, EscapeKind::Osc);
                }
                if bytes[i] == 0x1b && i + 1 < len && bytes[i + 1] == b'\\' {
                    i += 2;
                    return (i, i, EscapeKind::Osc);
                }
                i += 1;
            }
            (len, len, EscapeKind::Incomplete)
        }
        0x20..=0x2F => {
            while i < len && (0x20..=0x2F).contains(&bytes[i]) {
                i += 1;
            }
            if i < len && (0x30..=0x7E).contains(&bytes[i]) {
                i += 1;
                (i, i, EscapeKind::NF)
            } else if i < len {
                i += 1;
                (i, i, EscapeKind::NF)
            } else {
                (len, len, EscapeKind::Incomplete)
            }
        }
        _ => {
            // Two-byte sequence. The sequence text includes the character, but the following
            // text resumes right after the ESC byte.
            let end = next_char_boundary(bytes, i);
            (end, i, EscapeKind::Fe)
        }
    }
}

fn next_char_boundary(bytes: &[u8], i: usize) -> usize {
    let mut j = i + 1;
    while j < bytes.len() && (bytes[j] & 0xC0) == 0x80 {
        j += 1;
    }
    j
}

impl<'a> Iterator for AnsiCodeIterator<'a> {
    type Item = (&'a str, bool);

    fn next(&mut self) -> Option<Self::Item> {
        let bytes = self.s.as_bytes();
        if self.pos >= bytes.len() {
            return None;
        }
        if bytes[self.pos] == 0x1b {
            let (end, next, _kind) = escape_sequence_extent(bytes, self.pos);
            let chunk = &self.s[self.pos..end];
            self.pos = next;
            Some((chunk, true))
        } else {
            let start = self.pos;
            let mut i = start;
            while i < bytes.len() && bytes[i] != 0x1b {
                i += 1;
            }
            self.pos = i;
            Some((&self.s[start..i], false))
        }
    }
}

