#[derive(Debug, Default, Clone)]
struct Attributes {
    foreground: String,
    background: String,
    underline_color: String,
    charset: String,
    bold: String,
    dim: String,
    underline: String,
    italic: String,
    hyperlink: Option<String>,
}

impl Attributes {
    fn new() -> Self {
        Attributes::default()
    }

    /// Update the attributes with an escape sequence. Returns false if the sequence is
    /// unsupported.
    fn update(&mut self, sequence: &str) -> bool {
        let bytes = sequence.as_bytes();
        if bytes.len() < 2 || bytes[0] != 0x1b {
            return false;
        }
        match bytes[1] {
            b'[' => {
                let body = &sequence[2..];
                let Some(last) = body.as_bytes().last() else { return false };
                if *last != b'm' {
                    return false;
                }
                let params = &body[..body.len() - 1];
                self.update_with_sgr(params);
                true
            }
            b']' => {
                let body = &sequence[2..];
                if body.starts_with("8;") {
                    self.hyperlink = Some(sequence.to_string());
                    true
                } else {
                    false
                }
            }
            b'(' | b')' => {
                self.charset = sequence.to_string();
                true
            }
            _ => false,
        }
    }

    fn update_with_sgr(&mut self, params: &str) {
        let parts: Vec<&str> = params.split(';').collect();
        let mut iter = parts.into_iter();
        while let Some(p) = iter.next() {
            // Parameters with sub-parameters (e.g. "4:3") are not supported.
            if p.contains(':') {
                continue;
            }
            match p {
                "" | "0" => self.sgr_reset(),
                "1" => self.bold = "\x1b[1m".to_string(),
                "2" => self.dim = "\x1b[2m".to_string(),
                "3" => self.italic = "\x1b[3m".to_string(),
                "4" => self.underline = "\x1b[4m".to_string(),
                "22" => {
                    self.bold.clear();
                    self.dim.clear();
                }
                "23" => self.italic.clear(),
                "24" => self.underline.clear(),
                "30" | "31" | "32" | "33" | "34" | "35" | "36" | "37" | "90" | "91" | "92" | "93"
                | "94" | "95" | "96" | "97" => {
                    self.foreground = format!("\x1b[{}m", p);
                }
                "39" => self.foreground.clear(),
                "40" | "41" | "42" | "43" | "44" | "45" | "46" | "47" | "100" | "101" | "102"
                | "103" | "104" | "105" | "106" | "107" => {
                    self.background = format!("\x1b[{}m", p);
                }
                "49" => self.background.clear(),
                "38" | "48" | "58" => {
                    let value = Self::parse_extended_color(p, &mut iter);
                    if let Some(v) = value {
                        match p {
                            "38" => self.foreground = v,
                            "48" => self.background = v,
                            _ => self.underline_color = v,
                        }
                    }
                }
                "59" => self.underline_color.clear(),
                _ => {}
            }
        }
    }

    fn parse_extended_color<'b>(
        code: &str,
        iter: &mut impl Iterator<Item = &'b str>,
    ) -> Option<String> {
        let kind = iter.next()?;
        match kind {
            "5" => {
                let n = iter.next().unwrap_or("");
                Some(format!("\x1b[{};5;{}m", code, n))
            }
            "2" => {
                let mut comps = Vec::new();
                for _ in 0..3 {
                    match iter.next() {
                        Some(c) => comps.push(c),
                        None => break,
                    }
                }
                Some(format!("\x1b[{};2;{}m", code, comps.join(";")))
            }
            other => Some(format!("\x1b[{};{}m", code, other)),
        }
    }

    fn sgr_reset(&mut self) {
        self.foreground.clear();
        self.background.clear();
        self.underline_color.clear();
        self.bold.clear();
        self.dim.clear();
        self.underline.clear();
        self.italic.clear();
    }

    fn to_reset_sequence(&self) -> String {
        if self.hyperlink.is_some() {
            "\x1b]8;;\x1b\\".to_string()
        } else {
            String::new()
        }
    }
}

impl Display for Attributes {
    fn fmt(&self, f: &mut Formatter) -> std::fmt::Result {
        write!(
            f,
            "{}{}{}{}{}{}{}{}{}",
            self.foreground,
            self.background,
            self.underline_color,
            self.charset,
            self.bold,
            self.dim,
            self.underline,
            self.italic,
            self.hyperlink.as_deref().unwrap_or("")
        )
    }
}
