                Some(format!("\x1b[{};2;{}m", code, comps.join(";")))
            }
            other => Some(format!("\x1b[{};{}m", code, other)),
        }
    }

    fn sgr_reset(&mut self) {
        self.foreground.clear();
        self.background.clear();
        self.underline_color.clear();
        self.bold.clear();
        self.dim.clear();
        self.underline.clear();
        self.italic.clear();
    }

    fn to_reset_sequence(&self) -> String {
        if self.hyperlink.is_some() {
            "\x1b]8;;\x1b\\".to_string()
        } else {
            String::new()
        }
    }
}

impl Display for Attributes {
    fn fmt(&self, f: &mut Formatter) -> std::fmt::Result {
        write!(
            f,
            "{}{}{}{}{}{}{}{}{}",
            self.foreground,
            self.background,
            self.underline_color,
            self.charset,
            self.bold,
            self.dim,
            self.underline,
            self.italic,
            self.hyperlink.as_deref().unwrap_or("")
        )
    }
}
