use std::io::Write;

use unicode_width::UnicodeWidthChar;

use crate::assets::HighlightingAssets;
use crate::config::{BinaryBehavior, Config, StripAnsiMode, WrappingMode};
use crate::decorations::{Decoration, GridBorderDecoration, LineChangesDecoration, LineNumberDecoration};
use crate::diff::LineChanges;
use crate::error::*;
use crate::highlight::LineHighlighter;
use crate::input::{ContentType, OpenedInput, OpenedInputKind};
use crate::line_range::RangeCheckResult;
use crate::preprocessor::{expand_tabs, replace_nonprintable};
use crate::terminal::{as_terminal_escaped, to_ansi_color, Color, HlStyle, Style, ThemeColor};
use crate::theme::Theme;
use crate::vscreen::{strip_ansi, AnsiCodeIterator, AnsiStyle};

pub type OutputHandle<'a> = &'a mut dyn Write;

pub trait Printer {
    fn print_header(&mut self, handle: OutputHandle, input: &OpenedInput, add_header_padding: bool) -> Result<()>;
    fn print_footer(&mut self, handle: OutputHandle, input: &OpenedInput) -> Result<()>;
    fn print_snip(&mut self, handle: OutputHandle) -> Result<()>;
    fn print_line(&mut self, out_of_range: bool, handle: OutputHandle, line_number: usize, line_buffer: &[u8]) -> Result<()>;
}

pub struct SimplePrinter<'a> {
    config: &'a Config,
    consecutive_empty_lines: usize,
}

impl<'a> SimplePrinter<'a> {
    pub fn new(config: &'a Config) -> Self {
        SimplePrinter { config, consecutive_empty_lines: 0 }
    }
}

impl<'a> Printer for SimplePrinter<'a> {
    fn print_header(&mut self, _handle: OutputHandle, _input: &OpenedInput, _add_header_padding: bool) -> Result<()> {
        Ok(())
    }
    fn print_footer(&mut self, _handle: OutputHandle, _input: &OpenedInput) -> Result<()> {
        Ok(())
    }
    fn print_snip(&mut self, _handle: OutputHandle) -> Result<()> {
        Ok(())
    }
    fn print_line(&mut self, out_of_range: bool, handle: OutputHandle, _line_number: usize, line_buffer: &[u8]) -> Result<()> {
        // Skip squeezed lines.
        if let Some(squeeze_limit) = self.config.squeeze_lines {
            if is_empty_line(line_buffer) {
                self.consecutive_empty_lines += 1;
                if self.consecutive_empty_lines > squeeze_limit {
                    return Ok(());
                }
            } else {
                self.consecutive_empty_lines = 0;
            }
        }

        if !out_of_range {
            if self.config.show_nonprintable {
                let line = replace_nonprintable(line_buffer, self.config.tab_width, self.config.nonprintable_notation);
                write!(handle, "{}", line)?;
            } else {
                handle.write_all(line_buffer)?;
            }
        }
        Ok(())
    }
}

fn is_empty_line(line_buffer: &[u8]) -> bool {
    let mut end = line_buffer.len();
    while end > 0 && (line_buffer[end - 1] == b'\n' || line_buffer[end - 1] == b'\r') {
        end -= 1;
    }
    end == 0
}

#[derive(Debug, Clone, Copy, Default)]
pub struct Colors {
    pub grid: Style,
    pub rule: Style,
    pub header_value: Style,
    pub git_added: Style,
    pub git_removed: Style,
    pub git_modified: Style,
    pub line_number: Style,
}

const DEFAULT_GUTTER_COLOR: u8 = 238;

impl Colors {
    fn plain() -> Self {
        Colors::default()
    }

    fn colored(theme: &Theme, true_color: bool) -> Self {
        let gutter_style = Style {
            foreground: match theme.settings.gutter_foreground {
                Some(c) => to_ansi_color(c, true_color),
                None => Some(Color::Fixed(DEFAULT_GUTTER_COLOR)),
            },
            ..Style::default()
        };

        Colors {
            grid: gutter_style,
            rule: gutter_style,
            header_value: Style::new().bold(),
            git_added: Color::Green.normal(),
            git_removed: Color::Red.normal(),
            git_modified: Color::Yellow.normal(),
            line_number: gutter_style,
        }
    }
}

pub struct InteractivePrinter<'a> {
    colors: Colors,
    config: &'a Config,
    decorations: Vec<Box<dyn Decoration>>,
    panel_width: usize,
    ansi_style: AnsiStyle,
    content_type: Option<ContentType>,
    pub line_changes: Option<LineChanges>,
    highlighter: Option<Box<dyn LineHighlighter>>,
    background_color_highlight: Option<ThemeColor>,
    consecutive_empty_lines: usize,
    strip_ansi: bool,
    plain_style: HlStyle,
}

impl<'a> InteractivePrinter<'a> {
    pub fn new(
        config: &'a Config,
        assets: &'a HighlightingAssets,
        input: &mut OpenedInput,
        line_changes: Option<LineChanges>,
    ) -> Result<Self> {
        let theme = assets.get_theme(&config.theme);

        let background_color_highlight = theme.settings.line_highlight;

        let colors = if config.colored_output {
            Colors::colored(theme, config.true_color)
        } else {
            Colors::plain()
        };

        // Create decorations.
        let mut decorations: Vec<Box<dyn Decoration>> = Vec::new();

        if config.style_components.numbers() {
            decorations.push(Box::new(LineNumberDecoration::new(&colors)));
        }

        if config.style_components.changes() {
            decorations.push(Box::new(LineChangesDecoration::new(&colors)));
        }

        let mut panel_width: usize = decorations.len() + decorations.iter().fold(0, |a, x| a + x.width());

        // The grid border decoration isn't added until after the panel_width calculation.
        if config.style_components.grid() && !decorations.is_empty() {
            decorations.push(Box::new(GridBorderDecoration::new(&colors)));
        }

        // Disable the panel if the terminal is too small.
        if config.term_width < (decorations.len() + decorations.iter().fold(0, |a, x| a + x.width())) + 5 {
            decorations.clear();
            panel_width = 0;
        }

        let is_binary = input.reader.content_type == Some(ContentType::Binary);
        let highlighter = if is_binary && !config.show_nonprintable && config.binary == BinaryBehavior::NoPrinting {
            None
        } else {
            let syntax = assets.get_syntax_for_input(config, input)?;
            Some(assets.highlighter(syntax, theme))
        };

        let strip_ansi = match config.strip_ansi {
            StripAnsiMode::Never => false,
            StripAnsiMode::Always => true,
            StripAnsiMode::Auto => match &highlighter {
                Some(h) => !h.is_plain_text(),
                None => false,
            },
        };

        let plain_style = HlStyle {
            foreground: theme.settings.foreground.unwrap_or(ThemeColor::rgb(0, 0, 0)),
            background: theme.settings.background.unwrap_or(ThemeColor::rgb(0, 0, 0)),
            font_style: 0,
        };

        Ok(InteractivePrinter {
            colors,
            config,
            decorations,
            content_type: input.reader.content_type,
            ansi_style: AnsiStyle::new(),
            panel_width,
            line_changes,
            highlighter,
            background_color_highlight,
            consecutive_empty_lines: 0,
            strip_ansi,
            plain_style,
        })
    }

    fn print_horizontal_line_term(&mut self, handle: OutputHandle, style: Style) -> Result<()> {
        writeln!(handle, "{}", style.paint(&"─".repeat(self.config.term_width)))?;
        Ok(())
    }

    fn print_horizontal_line(&mut self, handle: OutputHandle, grid_char: char) -> Result<()> {
        if self.panel_width == 0 {
            self.print_horizontal_line_term(handle, self.colors.grid)?;
        } else {
            let hline = "─".repeat(self.config.term_width - (self.panel_width + 1));
            let hline = format!("{}{}{}", "─".repeat(self.panel_width), grid_char, hline);
            writeln!(handle, "{}", self.colors.grid.paint(&hline))?;
        }
        Ok(())
    }

    fn create_fake_panel(&self, text: &str) -> String {
        if self.panel_width == 0 {
            return "".to_string();
        }

        let text_truncated: String = text.chars().take(self.panel_width - 1).collect();
        let text_filled: String = format!(
            "{}{}",
            text_truncated,
            " ".repeat(self.panel_width - 1 - text_truncated.len())
        );
        if self.config.style_components.grid() {
            format!("{} │ ", text_filled)
        } else {
            text_filled
        }
    }

    fn get_header_component_indent_length(&self) -> usize {
        if self.config.style_components.grid() && self.panel_width > 0 {
            self.panel_width + 2
        } else {
            self.panel_width
        }
    }

    fn print_header_component_indent(&mut self, handle: OutputHandle) -> Result<()> {
        if self.config.style_components.grid() {
            write!(
                handle,
                "{}{}",
                " ".repeat(self.panel_width),
                self.colors.grid.paint(if self.panel_width > 0 { "│ " } else { "" }),
            )?;
        } else {
            write!(handle, "{}", " ".repeat(self.panel_width))?;
        }
        Ok(())
    }

    fn print_header_component_with_indent(&mut self, handle: OutputHandle, content: &str) -> Result<()> {
        self.print_header_component_indent(handle)?;
        writeln!(handle, "{}", content)?;
        Ok(())
    }

    fn print_header_multiline_component(&mut self, handle: OutputHandle, content: &str) -> Result<()> {
        let mut content = content;
        let content_width = self.config.term_width - self.get_header_component_indent_length();
        while content.chars().count() > content_width {
            let (content_line, remaining) = split_at_width(content, content_width);
            self.print_header_component_with_indent(handle, content_line)?;
            content = remaining;
        }
        self.print_header_component_with_indent(handle, content)
    }

    fn preprocess(&self, text: &str, cursor: &mut usize) -> String {
        if self.config.tab_width > 0 {
            return expand_tabs(text, self.config.tab_width, cursor);
        }

        *cursor += text.len();
        text.to_string()
    }

    fn highlight_regions_for_line<'l>(&mut self, line: &'l str) -> Vec<(HlStyle, &'l str)> {
        match &mut self.highlighter {
            Some(h) => h.highlight_line(line),
            None => vec![(self.plain_style, line)],
        }
    }
}

fn split_at_width(s: &str, width: usize) -> (&str, &str) {
    let mut count = 0;
    for (idx, _) in s.char_indices() {
        if count == width {
            return (&s[..idx], &s[idx..]);
        }
        count += 1;
    }
    (s, "")
}

fn format_size(size: u64) -> String {
    // Human readable (SI) size, like the `bytesize` crate's Display impl.
    const UNITS: [&str; 6] = ["B", "KB", "MB", "GB", "TB", "PB"];
    if size < 1000 {
        return format!("{} B", size);
    }
    let mut value = size as f64;
    let mut unit = 0;
    while value >= 1000.0 && unit < UNITS.len() - 1 {
        value /= 1000.0;
        unit += 1;
    }
    format!("{:.1} {}", value, UNITS[unit])
}

impl<'a> Printer for InteractivePrinter<'a> {
    fn print_header(&mut self, handle: OutputHandle, input: &OpenedInput, add_header_padding: bool) -> Result<()> {
        if add_header_padding && self.config.style_components.rule() {
            self.print_horizontal_line_term(handle, self.colors.rule)?;
        }

        if !self.config.style_components.header() {
            if Some(ContentType::Binary) == self.content_type
                && !self.config.show_nonprintable
                && self.config.binary == BinaryBehavior::NoPrinting
            {
                writeln!(
                    handle,
                    "{}: Binary content from {} will not be printed to the terminal \
                     (but will be present if the output of 'bat' is piped). You can use 'bat -A' \
                     to show the binary file contents.",
                    "\x1b[33m[bat warning]\x1b[0m",
                    input.description.summary(),
                )?;
            } else if self.config.style_components.grid() {
                self.print_horizontal_line(handle, '┬')?;
            }
            return Ok(());
        }

        let mode = match self.content_type {
            Some(ContentType::Binary) => "   <BINARY>",
            Some(ContentType::Utf16LE) => "   <UTF-16LE>",
            Some(ContentType::Utf16BE) => "   <UTF-16BE>",
            None => "   <EMPTY>",
            _ => "",
        };

        let description = &input.description;

        if self.config.style_components.grid() {
            self.print_horizontal_line(handle, '┬')?;
        } else if add_header_padding && !self.config.style_components.rule() {
            // Only pad space between files, if we haven't already drawn a horizontal rule
            writeln!(handle)?;
        }

        if self.config.style_components.header_filename() {
            let header_filename = format!(
                "{}{}{}",
                description.kind().map(|kind| format!("{}: ", kind)).unwrap_or_else(|| "".into()),
                self.colors.header_value.paint(description.title()),
                mode
            );
            self.print_header_multiline_component(handle, &header_filename)?;
        }

        if self.config.style_components.header_filesize() {
            let bsize = match &input.kind {
                OpenedInputKind::OrdinaryFile(path) => std::fs::metadata(path)
                    .map(|m| format_size(m.len()))
                    .unwrap_or_else(|_| "-".into()),
                _ => "-".into(),
            };
            let header_filesize = format!("Size: {}", self.colors.header_value.paint(&bsize));
            self.print_header_multiline_component(handle, &header_filesize)?;
        }

        if self.config.style_components.grid() {
            if self.content_type.map_or(false, |c| is_text(c))
                || self.config.show_nonprintable
                || (self.content_type == Some(ContentType::Binary) && self.config.binary == BinaryBehavior::AsText)
            {
                self.print_horizontal_line(handle, '┼')?;
            } else {
                self.print_horizontal_line(handle, '┴')?;
            }
        }

        Ok(())
    }

    fn print_footer(&mut self, handle: OutputHandle, _input: &OpenedInput) -> Result<()> {
        if self.config.style_components.grid()
            && (self.content_type.map_or(false, |c| is_text(c))
                || self.config.show_nonprintable
                || (self.content_type == Some(ContentType::Binary) && self.config.binary == BinaryBehavior::AsText))
        {
            self.print_horizontal_line(handle, '┴')
        } else {
            Ok(())
        }
    }

    fn print_snip(&mut self, handle: OutputHandle) -> Result<()> {
        let panel = self.create_fake_panel(" ...");
        let panel_count = panel.chars().count();

        let title = "8<";
        let title_count = title.chars().count();

        let snip_left = "─ ".repeat((self.config.term_width - panel_count - (title_count / 2)) / 4);
        let snip_left_count = snip_left.chars().count();

        let snip_right = " ─".repeat((self.config.term_width - panel_count - snip_left_count - title_count) / 2);

        writeln!(
            handle,
            "{}",
            self.colors.grid.paint(&format!("{}{}{}{}", panel, snip_left, title, snip_right))
        )?;

        Ok(())
    }

    fn print_line(&mut self, out_of_range: bool, handle: OutputHandle, line_number: usize, line_buffer: &[u8]) -> Result<()> {
        let line = match self.content_type {
            Some(ContentType::Binary) | None if self.config.binary == BinaryBehavior::NoPrinting && !self.config.show_nonprintable => {
                return Ok(());
            }
            None => return Ok(()),
            Some(ContentType::Utf16LE) => decode_utf16(line_buffer, true),
            Some(ContentType::Utf16BE) => decode_utf16(line_buffer, false),
            _ => {
                let mut line = String::from_utf8_lossy(line_buffer).into_owned();
                if self.config.show_nonprintable {
                    line = replace_nonprintable(line.as_bytes(), self.config.tab_width, self.config.nonprintable_notation);
                } else if self.strip_ansi {
                    line = strip_ansi(&line);
                }
                line
            }
        };

        let regions = self.highlight_regions_for_line(&line);

        if out_of_range {
            return Ok(());
        }

        // Skip squeezed lines.
        if let Some(squeeze_limit) = self.config.squeeze_lines {
            if is_empty_line(line_buffer) {
                self.consecutive_empty_lines += 1;
                if self.consecutive_empty_lines > squeeze_limit {
                    return Ok(());
                }
            } else {
                self.consecutive_empty_lines = 0;
            }
        }

        let mut cursor: usize = 0;
        let mut cursor_max: usize = self.config.term_width;
        let mut cursor_total: usize = 0;
        let mut panel_wrap: Option<String> = None;

        // Line highlighting
        let highlight_this_line = self.config.highlighted_lines.0.check(line_number) == RangeCheckResult::InRange;

        if highlight_this_line && self.config.theme == "ansi" {
            self.ansi_style.update("\x1b[4m");
        }

        let background_color = self.background_color_highlight.filter(|_| highlight_this_line);

        // Line decorations.
        if self.panel_width > 0 {
            let decorations = self
                .decorations
                .iter()
                .map(|d| d.generate(line_number, false, self))
                .collect::<Vec<_>>();

            for deco in decorations {
                write!(handle, "{} ", deco.text)?;
                cursor_max -= deco.width + 1;
            }
        }

        // Line contents.
        if matches!(self.config.wrapping_mode, WrappingMode::NoWrapping(_)) {
            let true_color = self.config.true_color;
            let colored_output = self.config.colored_output;
            let italics = self.config.use_italic_text;

            for &(style, region) in &regions {
                let ansi_iterator = AnsiCodeIterator::new(region);
                for chunk in ansi_iterator {
                    match chunk {
                        // ANSI escape passthrough.
                        (ansi, true) => {
                            self.ansi_style.update(ansi);
                            write!(handle, "{}", ansi)?;
                        }

                        // Regular text.
                        (text, false) => {
                            let text = &*self.preprocess(text, &mut cursor_total);
                            let text_trimmed = text.trim_end_matches(|c| c == '\r' || c == '\n');

                            write!(
                                handle,
                                "{}",
                                as_terminal_escaped(
                                    style,
                                    &format!("{}{}", self.ansi_style, text_trimmed),
                                    true_color,
                                    colored_output,
                                    italics,
                                    background_color
                                )
                            )?;
                            write!(handle, "{}", self.ansi_style.to_reset_sequence())?;

                            if text.len() != text_trimmed.len() {
                                if let Some(background_color) = background_color {
                                    let ansi_style = Style {
                                        background: to_ansi_color(background_color, true_color),
                                        ..Style::default()
                                    };

                                    let width = if cursor_total <= cursor_max {
                                        cursor_max - cursor_total
                                    } else {
                                        0
                                    };
                                    write!(handle, "{}", ansi_style.paint(&" ".repeat(width)))?;
                                }
                                write!(handle, "{}", &text[text_trimmed.len()..])?;
                            }
                        }
                    }
                }
            }
        } else {
            for &(style, region) in &regions {
                let ansi_iterator = AnsiCodeIterator::new(region);
                for chunk in ansi_iterator {
                    match chunk {
                        // ANSI escape passthrough.
                        (ansi, true) => {
                            self.ansi_style.update(ansi);
                            write!(handle, "{}", ansi)?;
                        }

                        // Regular text.
                        (text, false) => {
                            let text = self.preprocess(
                                text.trim_end_matches(|c| c == '\r' || c == '\n'),
                                &mut cursor_total,
                            );

                            let mut max_width = cursor_max - cursor;

                            // line buffer (avoid calling write! for every character)
                            let mut line_buf = String::with_capacity(max_width * 4);

                            // Displayed width of line_buf
                            let mut current_width = 0;

                            for c in text.chars() {
                                // calculate the displayed width for next character
                                let cw = c.width().unwrap_or(0);
                                current_width += cw;

                                // if next character cannot be printed on this line,
                                // flush the buffer.
                                if current_width > max_width {
                                    // Generate wrap padding if not already generated.
                                    if panel_wrap.is_none() {
                                        panel_wrap = if self.panel_width > 0 {
                                            Some(format!(
                                                "{} ",
                                                self.decorations
                                                    .iter()
                                                    .map(|d| d.generate(line_number, true, self).text)
                                                    .collect::<Vec<String>>()
                                                    .join(" ")
                                            ))
                                        } else {
                                            Some("".to_string())
                                        }
                                    }

                                    // It wraps.
                                    write!(
                                        handle,
                                        "{}{}\n{}",
                                        as_terminal_escaped(
                                            style,
                                            &format!("{}{}", self.ansi_style, line_buf),
                                            self.config.true_color,
                                            self.config.colored_output,
                                            self.config.use_italic_text,
                                            background_color
                                        ),
                                        self.ansi_style.to_reset_sequence(),
                                        panel_wrap.clone().unwrap()
                                    )?;

                                    cursor = 0;
                                    max_width = cursor_max;

                                    line_buf.clear();
                                    current_width = cw;
                                }

                                line_buf.push(c);
                            }

                            // flush the buffer
                            cursor += current_width;
                            write!(
                                handle,
                                "{}{}",
                                as_terminal_escaped(
                                    style,
                                    &format!("{}{}", self.ansi_style, line_buf),
                                    self.config.true_color,
                                    self.config.colored_output,
                                    self.config.use_italic_text,
                                    background_color
                                ),
                                self.ansi_style.to_reset_sequence()
                            )?;
                        }
                    }
                }
            }

            if let Some(background_color) = background_color {
                let ansi_style = Style {
                    background: to_ansi_color(background_color, self.config.true_color),
                    ..Style::default()
                };

                write!(
                    handle,
                    "{}",
                    ansi_style.paint(&" ".repeat(cursor_max - cursor))
                )?;
            }
            writeln!(handle)?;
        }

        if highlight_this_line && self.config.theme == "ansi" {
            self.ansi_style.update("\x1b[24m");
            write!(handle, "\x1b[24m")?;
        }

        Ok(())
    }
}

fn is_text(c: ContentType) -> bool {
    !matches!(c, ContentType::Binary)
}

fn decode_utf16(buf: &[u8], little_endian: bool) -> String {
    let mut data = buf;
    // Remove BOM
    if little_endian && data.starts_with(&[0xFF, 0xFE]) {
        data = &data[2..];
    } else if !little_endian && data.starts_with(&[0xFE, 0xFF]) {
        data = &data[2..];
    }
    let units: Vec<u16> = data
        .chunks(2)
        .map(|c| {
            let lo = c[0] as u16;
            let hi = if c.len() > 1 { c[1] as u16 } else { 0 };
            if little_endian {
                lo | (hi << 8)
            } else {
                (lo << 8) | hi
            }
        })
        .collect();
    let mut s = String::from_utf16_lossy(&units);
    if data.len() % 2 == 1 {
        s.push('\u{FFFD}');
    }
    s
}
