                        let mut printer = SimplePrinter::new(self.config);
                        self.print_file(&mut printer, output, &mut opened_input, identifier > 0, line_changes)
                    } else {
                        match InteractivePrinter::new(self.config, self.assets, &mut opened_input, line_changes) {
                            Ok(mut printer) => {
                                self.print_file(&mut printer, output, &mut opened_input, identifier > 0, None)
                            }
                            Err(e) => Err(e),
                        }
                    };

