                        if let Error::Io(ref e) = error {
                            if e.kind() == std::io::ErrorKind::BrokenPipe {
                                return Err(error);
                            }
                        }
                        crate::error::default_error_handler(&error, &mut stderr.lock());
                        no_errors = false;
                    }
                }
            }
        }

        Ok(no_errors)
    }

    fn print_file(
        &self,
        printer: &mut dyn Printer,
        writer: &mut dyn Write,
        input: &mut OpenedInput,
        add_header_padding: bool,
        line_changes: Option<LineChanges>,
    ) -> Result<()> {
        let _ = line_changes;
        let is_empty = input.reader.first_line.is_empty();

        if self.config.quiet_empty && is_empty {
            return Ok(());
        }

        if !is_empty || self.config.style_components.header() {
            printer.print_header(writer, input, add_header_padding)?;
        }

        if !is_empty {
            let line_ranges = match self.config.diff_context {
                Some(context) => {
                    let changes = match input.kind {
                        OpenedInputKind::OrdinaryFile(ref path) => get_git_diff(path),
                        _ => None,
                    };
                    match changes {
                        Some(changes) => LineRanges::from(
                            changes
                                .keys()
                                .map(|line| {
                                    let line = *line as usize;
                                    LineRange::new(line.saturating_sub(context), line.saturating_add(context))
                                })
                                .collect(),
