        Ok(())
    }

    fn print_file_ranges(
        &self,
        printer: &mut dyn Printer,
        writer: &mut dyn Write,
        input: &mut OpenedInput,
        line_ranges: &LineRanges,
    ) -> Result<()> {
        let mut line_buffer = Vec::new();
        let mut line_number: usize = 1;

        let mut first_range: bool = true;
        let mut mid_range: bool = false;

        let style_snip = self.config.style_components.snip();

        // Ranges relative to the end of the input require knowing the total number of lines.
        let resolved_ranges;
        let mut buffered_lines: Option<std::collections::VecDeque<Vec<u8>>> = None;
        let line_ranges = if line_ranges.needs_total() {
            let mut all = Vec::new();
            input.reader.read_to_end(&mut all)?;
            let mut lines = std::collections::VecDeque::new();
            let mut start = 0;
            for (i, b) in all.iter().enumerate() {
                if *b == b'\n' {
                    lines.push_back(all[start..=i].to_vec());
                    start = i + 1;
                }
            }
            if start < all.len() {
                lines.push_back(all[start..].to_vec());
            }
            resolved_ranges = line_ranges.resolve(lines.len());
            buffered_lines = Some(lines);
            &resolved_ranges
        } else {
            line_ranges
        };

        loop {
            let has_line = match &mut buffered_lines {
                Some(lines) => match lines.pop_front() {
                    Some(l) => {
                        line_buffer = l;
                        true
                    }
                    None => false,
                },
                None => input.reader.read_line(&mut line_buffer)?,
            };
            if !has_line {
                break;
            }

            match line_ranges.check(line_number) {
                RangeCheckResult::BeforeOrBetweenRanges => {
                    // Call the printer in case we need to call the syntax highlighter
                    // for this line. However, we don't want to print anything.
                    printer.print_line(true, writer, line_number, &line_buffer)?;
                    mid_range = false;
                }

                RangeCheckResult::InRange => {
                    if style_snip {
                        if first_range {
                            first_range = false;
                            mid_range = true;
                        } else if !mid_range {
                            mid_range = true;
                            printer.print_snip(writer)?;
                        }
                    }

                    printer.print_line(false, writer, line_number, &line_buffer)?;
                }
                RangeCheckResult::AfterLastRange => {
                    break;
                }
            }

            line_number += 1;
            line_buffer.clear();
        }
        Ok(())
    }
}
