            .matches
            .get_one::<String>("theme-light")
            .map(|s| s.to_owned())
            .or_else(|| env::var("BAT_THEME_LIGHT").ok())
            .unwrap_or_else(|| crate::theme::DEFAULT_LIGHT_THEME.to_owned());

