                    match crate::theme::detect_color_scheme() {
                        Some(crate::theme::ColorScheme::Light) => theme_light,
                        Some(crate::theme::ColorScheme::Dark) => theme_dark,
                        None => crate::theme::DEFAULT_THEME.to_owned(),
                    }
                } else {
                    crate::theme::DEFAULT_THEME.to_owned()
                }
            }
            "auto:always" => match crate::theme::detect_color_scheme() {
                Some(crate::theme::ColorScheme::Light) => theme_light,
                Some(crate::theme::ColorScheme::Dark) => theme_dark,
                None => crate::theme::DEFAULT_THEME.to_owned(),
            },
            "auto:system" => {
                crate::bat_warning!("Theme 'auto:system' is only supported on macOS, using default.");
