use std::path::{Path, PathBuf};
use std::sync::OnceLock;

pub struct BatProjectDirs {
    cache_dir: PathBuf,
    config_dir: PathBuf,
}

impl BatProjectDirs {
    fn new() -> Option<BatProjectDirs> {
        let cache_dir = BatProjectDirs::get_cache_dir()?;

        let config_dir_op = std::env::var_os("XDG_CONFIG_HOME")
            .map(PathBuf::from)
            .filter(|p| p.is_absolute())
            .or_else(|| dirs::home_dir().map(|d| d.join(".config")));

        let config_dir = config_dir_op.map(|d| d.join("bat"))?;

        Some(BatProjectDirs { cache_dir, config_dir })
    }

    fn get_cache_dir() -> Option<PathBuf> {
        // on all OS prefer BAT_CACHE_PATH if set
        let cache_dir_op = std::env::var_os("BAT_CACHE_PATH").map(PathBuf::from);
        if cache_dir_op.is_some() {
            return cache_dir_op;
        }

        let cache_dir_op = std::env::var_os("XDG_CACHE_HOME")
            .map(PathBuf::from)
            .filter(|p| p.is_absolute())
            .or_else(|| dirs::home_dir().map(|d| d.join(".cache")));

        cache_dir_op.map(|d| d.join("bat"))
    }

    pub fn cache_dir(&self) -> &Path {
        &self.cache_dir
    }

    pub fn config_dir(&self) -> &Path {
        &self.config_dir
    }
}

pub struct ProjectDirsHolder;

impl ProjectDirsHolder {
    fn get() -> &'static BatProjectDirs {
        static DIRS: OnceLock<BatProjectDirs> = OnceLock::new();
        DIRS.get_or_init(|| {
            BatProjectDirs::new().unwrap_or_else(|| {
                eprintln!("Could not get home directory");
                std::process::exit(1)
            })
        })
    }
    pub fn cache_dir(&self) -> &Path {
        Self::get().cache_dir()
    }
    pub fn config_dir(&self) -> &Path {
        Self::get().config_dir()
    }
}

pub static PROJECT_DIRS: ProjectDirsHolder = ProjectDirsHolder;
