/// Resolve the style for a scope stack using the theme's rules (most specific wins, later wins on ties).
pub fn style_for_scopes(theme: &Theme, scopes: &[&str]) -> HlStyle {
    let mut style = theme.default_style();
    let mut best: Vec<(crate::scope::MatchPower, &StyleModifier)> = Vec::new();
    for item in &theme.items {
        if let Some(power) = crate::scope::selector_matches(item.selector, scopes) {
            best.push((power, &item.style));
        }
    }
    best.sort_by(|a, b| a.0.cmp(&b.0));
    for (_, m) in best {
        if let Some(f) = m.foreground {
            style.foreground = f;
        }
        if let Some(b) = m.background {
            style.background = b;
        }
        if let Some(fs) = m.font_style {
            style.font_style = fs;
        }
    }
    style
}

