#[derive(Debug, Clone, Copy, PartialEq, PartialOrd)]
pub struct MatchPower(pub f64);

impl Eq for MatchPower {}
impl Ord for MatchPower {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.partial_cmp(other).unwrap_or(std::cmp::Ordering::Equal)
    }
}

const ATOM_LEN_BITS: u16 = 3;

/// Is `sel` a prefix of `scope` in terms of dot-separated atoms?
fn is_prefix_of(sel: &str, scope: &str) -> bool {
    if sel.is_empty() {
        return true;
    }
    if !scope.starts_with(sel) {
        return false;
    }
    scope.len() == sel.len() || scope.as_bytes()[sel.len()] == b'.'
}

fn atom_count(s: &str) -> usize {
    if s.is_empty() {
        0
    } else {
        s.split('.').count()
    }
}

fn path_does_match(path: &[&str], stack: &[&str]) -> Option<MatchPower> {
    let mut sel_index = 0;
    let mut score = 0.0f64;
    if path.is_empty() {
        return None;
    }
    for (i, scope) in stack.iter().enumerate() {
        let sel_scope = path[sel_index];
        if is_prefix_of(sel_scope, scope) {
            let len = atom_count(sel_scope) as f64;
            score += len * f64::from(ATOM_LEN_BITS * (i as u16)).exp2();
            sel_index += 1;
            if sel_index >= path.len() {
                return Some(MatchPower(score));
            }
        }
    }
    None
}

/// Match a selector string (with `,` alternatives and ` - ` exclusions) against a scope stack.
pub fn selector_matches(selector: &str, stack: &[&str]) -> Option<MatchPower> {
    let mut best: Option<MatchPower> = None;
    for alt in selector.split(|c| c == ',' || c == '|') {
        let alt = alt.trim();
        if alt.is_empty() {
            continue;
        }
        let mut parts = alt.split(" - ");
        let path_str = parts.next().unwrap().trim();
        let path: Vec<&str> = path_str.split_whitespace().collect();
        let mut excluded = false;
        for ex in parts {
            let ex_path: Vec<&str> = ex.split_whitespace().collect();
            if path_does_match(&ex_path, stack).is_some() {
                excluded = true;
                break;
            }
        }
        if excluded {
            continue;
        }
        if let Some(p) = path_does_match(&path, stack) {
            if best.map_or(true, |b| p > b) {
                best = Some(p);
            }
        }
    }
    best
}
