//! Sublime-syntax style syntax definitions and the parser producing scope operations.

use std::collections::HashMap;
use std::sync::Arc;

use fancy_regex::Regex;
use once_cell::sync::OnceCell;
use serde::Deserialize;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ScopeStackOp {
    Push(Arc<str>),
    Pop(usize),
    /// Clear `n` scopes from the stack (temporarily) (clear_scopes: n)
    Clear(ClearAmount),
    Restore,
    Noop,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ClearAmount {
    TopN(usize),
    All,
}

#[derive(Debug, Clone)]
pub enum ContextRef {
    Named(String),
    Inline(usize),
    ByScope { scope: String, sub_context: Option<String> },
    Direct(usize),
}

#[derive(Debug, Clone)]
pub enum MatchOperation {
    None,
    Push(Vec<ContextRef>),
    Set(Vec<ContextRef>),
    Pop(usize),
}

#[derive(Debug)]
pub struct MatchPattern {
    pub regex_str: String,
    pub has_backrefs: bool,
    regex: OnceCell<Option<Regex>>,
    pub scope: Vec<Arc<str>>,
    pub captures: Vec<(usize, Vec<Arc<str>>)>,
    pub operation: MatchOperation,
    pub with_prototype: Option<usize>,
}

impl MatchPattern {
    fn regex(&self) -> Option<&Regex> {
        self.regex
            .get_or_init(|| match Regex::new(&format!("(?m){}", self.regex_str)) {
                Ok(r) => Some(r),
                Err(e) => {
                    if std::env::var_os("BAT_DEBUG_SYNTAX").is_some() {
                        eprintln!("bad regex {:?}: {}", self.regex_str, e);
                    }
                    None
                }
            })
            .as_ref()
    }
}

#[derive(Debug)]
pub enum Pattern {
    Match(MatchPattern),
    Include(ContextRef),
}

#[derive(Debug, Default)]
pub struct Context {
    pub name: String,
    pub meta_scope: Vec<Arc<str>>,
    pub meta_content_scope: Vec<Arc<str>>,
    pub meta_include_prototype: bool,
    pub clear_scopes: Option<ClearAmount>,
    pub patterns: Vec<Pattern>,
    pub uses_backrefs: bool,
}

#[derive(Debug)]
pub struct SyntaxDefinition {
    pub name: String,
    pub scope: String,
    pub file_extensions: Vec<String>,
    pub first_line_match: Option<String>,
    pub hidden: bool,
    pub contexts: Vec<Context>,
    pub context_names: HashMap<String, usize>,
}

impl SyntaxDefinition {
    pub fn main_context(&self) -> Option<usize> {
        self.context_names.get("main").copied()
    }
    pub fn context_index(&self, name: &str) -> Option<usize> {
        self.context_names.get(name).copied()
    }
}

// ---------------------------------------------------------------------------
// YAML loading
// ---------------------------------------------------------------------------

#[derive(Deserialize, Debug)]
struct RawSyntax {
    name: String,
    #[serde(default)]
    scope: String,
    #[serde(default)]
    file_extensions: Vec<String>,
    #[serde(default)]
    first_line_match: Option<String>,
    #[serde(default)]
    hidden: bool,
    #[serde(default)]
    variables: HashMap<String, String>,
    contexts: HashMap<String, Vec<serde_yaml::Value>>,
}

fn sv(v: &serde_yaml::Value) -> Option<String> {
    match v {
        serde_yaml::Value::String(s) => Some(s.clone()),
        serde_yaml::Value::Number(n) => Some(n.to_string()),
        serde_yaml::Value::Bool(b) => Some(b.to_string()),
        _ => None,
    }
}

fn scopes_from(s: &str) -> Vec<Arc<str>> {
    s.split_whitespace().map(|x| Arc::from(x)).collect()
}

struct Loader<'a> {
    variables: &'a HashMap<String, String>,
    contexts: Vec<Context>,
    names: HashMap<String, usize>,
    anon_counter: usize,
}

impl<'a> Loader<'a> {
    fn resolve_variables(&self, s: &str) -> String {
        let mut out = s.to_string();
        for _ in 0..20 {
            if !out.contains("{{") {
                break;
            }
            let mut res = String::new();
            let mut rest = out.as_str();
            let mut changed = false;
            while let Some(start) = rest.find("{{") {
                res.push_str(&rest[..start]);
                let after = &rest[start + 2..];
                if let Some(end) = after.find("}}") {
                    let name = &after[..end];
                    if let Some(val) = self.variables.get(name) {
                        res.push_str(val);
                        changed = true;
                    } else {
                        res.push_str("{{");
                        res.push_str(name);
                        res.push_str("}}");
                    }
                    rest = &after[end + 2..];
                } else {
                    res.push_str("{{");
                    rest = after;
                }
            }
            res.push_str(rest);
            out = res;
            if !changed {
                break;
            }
        }
        out
    }

    fn new_context(&mut self, name: String) -> usize {
        let idx = self.contexts.len();
        self.contexts.push(Context {
            name: name.clone(),
            meta_include_prototype: true,
            ..Default::default()
        });
        self.names.entry(name).or_insert(idx);
        idx
    }

    fn parse_context_ref(&mut self, v: &serde_yaml::Value, parent: &str) -> Vec<ContextRef> {
        match v {
            serde_yaml::Value::String(s) => vec![self.parse_context_ref_str(s)],
            serde_yaml::Value::Sequence(seq) => {
                // Either a list of names, or an inline context (list of patterns)
                let is_inline = seq.iter().any(|x| matches!(x, serde_yaml::Value::Mapping(_)));
                if is_inline {
                    self.anon_counter += 1;
                    let name = format!("{}#anon{}", parent, self.anon_counter);
                    let idx = self.new_context(name.clone());
                    self.fill_context(idx, seq, &name);
                    vec![ContextRef::Inline(idx)]
                } else {
                    let mut refs = Vec::new();
                    for x in seq {
                        if let serde_yaml::Value::Sequence(inner) = x {
                            self.anon_counter += 1;
                            let name = format!("{}#anon{}", parent, self.anon_counter);
                            let idx = self.new_context(name.clone());
                            self.fill_context(idx, inner, &name);
                            refs.push(ContextRef::Inline(idx));
                        } else if let Some(s) = sv(x) {
                            refs.push(self.parse_context_ref_str(&s));
                        }
                    }
                    refs
                }
            }
            _ => vec![],
        }
    }

    fn parse_context_ref_str(&self, s: &str) -> ContextRef {
        if let Some(rest) = s.strip_prefix("scope:") {
            let mut parts = rest.splitn(2, '#');
            let scope = parts.next().unwrap().to_string();
            let sub = parts.next().map(|x| x.to_string());
            ContextRef::ByScope { scope, sub_context: sub }
        } else {
            ContextRef::Named(s.to_string())
        }
    }

    fn fill_context(&mut self, idx: usize, items: &[serde_yaml::Value], name: &str) {
        let mut patterns = Vec::new();
        let mut meta_scope = Vec::new();
        let mut meta_content_scope = Vec::new();
        let mut meta_include_prototype = true;
        let mut clear_scopes = None;
        let mut uses_backrefs = false;
        for item in items {
            let serde_yaml::Value::Mapping(map) = item else { continue };
            let get = |k: &str| map.get(serde_yaml::Value::String(k.to_string()));
            if let Some(ms) = get("meta_scope") {
                meta_scope.extend(scopes_from(&sv(ms).unwrap_or_default()));
            } else if let Some(ms) = get("meta_content_scope") {
                meta_content_scope.extend(scopes_from(&sv(ms).unwrap_or_default()));
            } else if let Some(v) = get("meta_include_prototype") {
                meta_include_prototype = v.as_bool().unwrap_or(true);
            } else if let Some(v) = get("clear_scopes") {
                clear_scopes = match v {
                    serde_yaml::Value::Bool(true) => Some(ClearAmount::All),
                    serde_yaml::Value::Number(n) => n.as_u64().map(|n| ClearAmount::TopN(n as usize)),
                    _ => None,
                };
            } else if let Some(inc) = get("include") {
                if let Some(s) = sv(inc) {
                    patterns.push(Pattern::Include(self.parse_context_ref_str(&s)));
                }
            } else if let Some(m) = get("match") {
                let raw = sv(m).unwrap_or_default();
                let regex_str = self.resolve_variables(&raw);
                let has_backrefs = has_backreference(&regex_str);
                if has_backrefs {
                    uses_backrefs = true;
                }
                let scope = get("scope").and_then(sv).map(|s| scopes_from(&s)).unwrap_or_default();
                let mut captures = Vec::new();
                if let Some(serde_yaml::Value::Mapping(caps)) = get("captures") {
                    for (k, v) in caps {
                        let k = match k {
                            serde_yaml::Value::Number(n) => n.as_u64().unwrap_or(0) as usize,
                            serde_yaml::Value::String(s) => s.parse().unwrap_or(0),
                            _ => continue,
                        };
                        captures.push((k, scopes_from(&sv(v).unwrap_or_default())));
                    }
                    captures.sort_by_key(|(k, _)| *k);
                }
                let mut with_prototype = None;
                if let Some(wp) = get("with_prototype") {
                    if let serde_yaml::Value::Sequence(seq) = wp {
                        self.anon_counter += 1;
                        let pname = format!("{}#proto{}", name, self.anon_counter);
                        let pidx = self.new_context(pname.clone());
                        self.fill_context(pidx, seq, &pname);
                        self.contexts[pidx].meta_include_prototype = false;
                        with_prototype = Some(pidx);
                    }
                }
                let operation = if let Some(p) = get("pop") {
                    match p {
                        serde_yaml::Value::Bool(true) => MatchOperation::Pop(1),
                        serde_yaml::Value::Number(n) => MatchOperation::Pop(n.as_u64().unwrap_or(1) as usize),
                        _ => MatchOperation::None,
                    }
                } else if let Some(p) = get("push") {
                    MatchOperation::Push(self.parse_context_ref(p, name))
                } else if let Some(p) = get("set") {
                    MatchOperation::Set(self.parse_context_ref(p, name))
                } else if let Some(e) = get("embed") {
                    // embed: emulate with a push of a context containing the embedded one,
                    // with the escape pattern as prototype.
                    let embed_refs = self.parse_context_ref(e, name);
                    let embed_scope = get("embed_scope").and_then(sv).map(|s| scopes_from(&s)).unwrap_or_default();
                    self.anon_counter += 1;
                    let ename = format!("{}#embed{}", name, self.anon_counter);
                    let eidx = self.new_context(ename.clone());
                    {
                        let ctx = &mut self.contexts[eidx];
                        ctx.meta_content_scope = embed_scope;
                        ctx.meta_include_prototype = false;
                        for r in embed_refs {
                            ctx.patterns.push(Pattern::Include(r));
                        }
                    }
                    if let Some(esc) = get("escape").and_then(sv) {
                        let esc_regex = self.resolve_variables(&esc);
                        let mut esc_caps = Vec::new();
                        if let Some(serde_yaml::Value::Mapping(caps)) = get("escape_captures") {
                            for (k, v) in caps {
                                let k = match k {
                                    serde_yaml::Value::Number(n) => n.as_u64().unwrap_or(0) as usize,
                                    serde_yaml::Value::String(s) => s.parse().unwrap_or(0),
                                    _ => continue,
                                };
                                esc_caps.push((k, scopes_from(&sv(v).unwrap_or_default())));
                            }
                            esc_caps.sort_by_key(|(k, _)| *k);
                        }
                        self.anon_counter += 1;
                        let pname = format!("{}#escape{}", name, self.anon_counter);
                        let pidx = self.new_context(pname);
                        let has_br = has_backreference(&esc_regex);
                        self.contexts[pidx].meta_include_prototype = false;
                        self.contexts[pidx].uses_backrefs = has_br;
                        self.contexts[pidx].patterns.push(Pattern::Match(MatchPattern {
                            regex_str: esc_regex,
                            has_backrefs: has_br,
                            regex: OnceCell::new(),
                            scope: Vec::new(),
                            captures: esc_caps,
                            operation: MatchOperation::Pop(1),
                            with_prototype: None,
                        }));
                        with_prototype = Some(pidx);
                    }
                    MatchOperation::Push(vec![ContextRef::Inline(eidx)])
                } else {
                    MatchOperation::None
                };
                patterns.push(Pattern::Match(MatchPattern {
                    regex_str,
                    has_backrefs,
                    regex: OnceCell::new(),
                    scope,
                    captures,
                    operation,
                    with_prototype,
                }));
            }
        }
        let ctx = &mut self.contexts[idx];
        ctx.meta_scope = meta_scope;
        ctx.meta_content_scope = meta_content_scope;
        ctx.meta_include_prototype = meta_include_prototype;
        ctx.clear_scopes = clear_scopes;
        ctx.patterns = patterns;
        ctx.uses_backrefs = uses_backrefs;
    }
}

fn has_backreference(re: &str) -> bool {
    let b = re.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'\\' {
            if i + 1 < b.len() {
                if b[i + 1].is_ascii_digit() && b[i + 1] != b'0' {
                    return true;
                }
                i += 2;
                continue;
            }
        }
        i += 1;
    }
    false
}

pub fn load_syntax(yaml: &str) -> Result<SyntaxDefinition, String> {
    let raw: RawSyntax = serde_yaml::from_str(yaml).map_err(|e| e.to_string())?;
    let mut loader = Loader {
        variables: &raw.variables,
        contexts: Vec::new(),
        names: HashMap::new(),
        anon_counter: 0,
    };
    // resolve nested variables
    let mut vars = raw.variables.clone();
    for _ in 0..10 {
        let mut changed = false;
        let snapshot = vars.clone();
        let tmp = Loader { variables: &snapshot, contexts: Vec::new(), names: HashMap::new(), anon_counter: 0 };
        for (k, v) in vars.iter_mut() {
            let nv = tmp.resolve_variables(v);
            if nv != *v {
                *v = nv;
                changed = true;
            }
            let _ = k;
        }
        if !changed {
            break;
        }
    }
    loader.variables = &vars;

    // create all named contexts first (so that references resolve)
    let mut names: Vec<&String> = raw.contexts.keys().collect();
    names.sort();
    for n in &names {
        loader.new_context((*n).clone());
    }
    for n in names {
        let idx = loader.names[n];
        let items = raw.contexts[n].clone();
        loader.fill_context(idx, &items, n);
    }
    // prepend prototype include
    if let Some(&proto) = loader.names.get("prototype") {
        for (i, ctx) in loader.contexts.iter_mut().enumerate() {
            if i != proto && ctx.meta_include_prototype && !ctx.name.contains("#proto") && !ctx.name.contains("#escape") {
                ctx.patterns.insert(0, Pattern::Include(ContextRef::Direct(proto)));
            }
        }
    }
    let Loader { contexts, names, .. } = loader;
    Ok(SyntaxDefinition {
        name: raw.name,
        scope: raw.scope,
        file_extensions: raw.file_extensions,
        first_line_match: raw.first_line_match,
        hidden: raw.hidden,
        contexts,
        context_names: names,
    })
}
EOF
echo ok"}

