//! Line parser: produces scope stack operations for a line of text.

use std::collections::HashMap;
use std::sync::Arc;

use fancy_regex::Regex;

use crate::syntax::*;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct CtxId {
    pub syntax: usize,
    pub ctx: usize,
}

pub struct SyntaxSet {
    pub syntaxes: Vec<SyntaxDefinition>,
    by_scope: HashMap<String, usize>,
    backref_cache: std::cell::RefCell<HashMap<String, Option<Regex>>>,
}

impl SyntaxSet {
    pub fn new(syntaxes: Vec<SyntaxDefinition>) -> SyntaxSet {
        let mut by_scope = HashMap::new();
        for (i, s) in syntaxes.iter().enumerate() {
            by_scope.entry(s.scope.clone()).or_insert(i);
        }
        SyntaxSet {
            syntaxes,
            by_scope,
            backref_cache: std::cell::RefCell::new(HashMap::new()),
        }
    }

    pub fn context(&self, id: CtxId) -> &Context {
        &self.syntaxes[id.syntax].contexts[id.ctx]
    }

    pub fn find_by_scope(&self, scope: &str) -> Option<usize> {
        self.by_scope.get(scope).copied()
    }

    fn resolve_ref(&self, syntax: usize, r: &ContextRef) -> Option<CtxId> {
        match r {
            ContextRef::Named(n) => self.syntaxes[syntax].context_index(n).map(|c| CtxId { syntax, ctx: c }),
            ContextRef::Inline(i) | ContextRef::Direct(i) => Some(CtxId { syntax, ctx: *i }),
            ContextRef::ByScope { scope, sub_context } => {
                let s = self.find_by_scope(scope)?;
                let name = sub_context.as_deref().unwrap_or("main");
                self.syntaxes[s].context_index(name).map(|c| CtxId { syntax: s, ctx: c })
            }
        }
    }
}

#[derive(Debug, Clone)]
struct StateLevel {
    context: CtxId,
    prototypes: Vec<CtxId>,
    captures: Option<Arc<Vec<Option<String>>>>,
}

#[derive(Debug, Clone)]
pub struct ParseState {
    stack: Vec<StateLevel>,
    first_line: bool,
}

impl ParseState {
    pub fn new(set: &SyntaxSet, syntax: usize) -> ParseState {
        let main = set.syntaxes[syntax].main_context().unwrap_or(0);
        ParseState {
            stack: vec![StateLevel {
                context: CtxId { syntax, ctx: main },
                prototypes: Vec::new(),
                captures: None,
            }],
            first_line: true,
        }
    }

    pub fn initial_scopes(&self, set: &SyntaxSet) -> Vec<Arc<str>> {
        let mut v = Vec::new();
        for lvl in &self.stack {
            let ctx = set.context(lvl.context);
            v.extend(ctx.meta_scope.iter().cloned());
            v.extend(ctx.meta_content_scope.iter().cloned());
        }
        v
    }

    /// Parse a line, returning the scope operations (position, op).
    pub fn parse_line(&mut self, line: &str, set: &SyntaxSet) -> Vec<(usize, ScopeStackOp)> {
        let mut ops: Vec<(usize, ScopeStackOp)> = Vec::new();
        let mut start = 0usize;
        if self.first_line {
            // Push the initial scopes of the main context.
            let lvl = &self.stack[0];
            let ctx = set.context(lvl.context);
            for s in ctx.meta_scope.iter().chain(ctx.meta_content_scope.iter()) {
                ops.push((0, ScopeStackOp::Push(s.clone())));
            }
            self.first_line = false;
        }
        let mut non_consuming_push_at: Option<(usize, usize)> = None;
        let mut iterations = 0;
        while start <= line.len() {
            iterations += 1;
            if iterations > 10000 {
                break;
            }
            let Some(m) = self.find_best_match(line, start, set, non_consuming_push_at) else {
                break;
            };
            let (mstart, mend) = (m.start, m.end);
            let consuming = mend > mstart || mstart > start;
            let stack_len_before = self.stack.len();
            self.exec_pattern(line, &m, set, &mut ops);
            if !consuming {
                match m.operation_kind {
                    OpKind::PushOrSet => {
                        non_consuming_push_at = Some((mstart, self.stack.len()));
                        let _ = stack_len_before;
                    }
                    OpKind::Pop => {}
                    OpKind::None => {
                        // Zero width match with no stack change: avoid an infinite loop by
                        // remembering it like a non-consuming push.
                        non_consuming_push_at = Some((mstart, usize::MAX - m.pattern_index));
                    }
                }
            } else {
                non_consuming_push_at = None;
            }
            start = mend;
            if mend >= line.len() && mend == mstart && !matches!(m.operation_kind, OpKind::PushOrSet | OpKind::Pop) {
                break;
            }
        }
        ops
    }

    fn find_best_match(
        &self,
        line: &str,
        start: usize,
        set: &SyntaxSet,
        non_consuming_push_at: Option<(usize, usize)>,
    ) -> Option<FoundMatch> {
        let cur = self.stack.last().unwrap();
        // Collect the patterns in order: with_prototypes (outermost first), then the context.
        let mut candidates: Vec<(CtxId, usize)> = Vec::new(); // (context, pattern index)
        let mut visited = Vec::new();
        let mut proto_ctxs: Vec<CtxId> = Vec::new();
        for lvl in &self.stack {
            for p in &lvl.prototypes {
                if !proto_ctxs.contains(p) {
                    proto_ctxs.push(*p);
                }
            }
        }
        for p in &proto_ctxs {
            self.collect_patterns(*p, set, &mut candidates, &mut visited);
        }
        visited.clear();
        self.collect_patterns(cur.context, set, &mut candidates, &mut visited);

        let mut best: Option<FoundMatch> = None;
        let mut pat_counter = 0usize;
        for (ctx_id, pidx) in candidates {
            pat_counter += 1;
            let ctx = set.context(ctx_id);
            let Pattern::Match(pat) = &ctx.patterns[pidx] else { continue };
            let regex_holder;
            let regex: &Regex = if pat.has_backrefs {
                let caps = cur.captures.as_deref();
                let substituted = substitute_backrefs(&pat.regex_str, caps);
                let mut cache = set.backref_cache.borrow_mut();
                let entry = cache
                    .entry(substituted.clone())
                    .or_insert_with(|| Regex::new(&format!("(?m){}", substituted)).ok());
                match entry {
                    Some(r) => {
                        regex_holder = r.clone();
                        &regex_holder
                    }
                    None => continue,
                }
            } else {
                match pat.regex() {
                    Some(r) => r,
                    None => continue,
                }
            };
            let m = match regex.captures_from_pos(line, start) {
                Ok(Some(c)) => c,
                _ => continue,
            };
            let whole = m.get(0).unwrap();
            let (ms, me) = (whole.start(), whole.end());
            // Skip non-consuming pushes that would loop.
            if ms == me && ms == start {
                if let Some((p, depth)) = non_consuming_push_at {
                    if p == start {
                        let is_push = matches!(pat.operation, MatchOperation::Push(_) | MatchOperation::Set(_));
                        let is_none = matches!(pat.operation, MatchOperation::None);
                        if is_push && depth == self.stack.len() {
                            continue;
                        }
                        if is_none && depth == usize::MAX - pat_counter {
                            continue;
                        }
                    }
                }
            }
            if best.as_ref().map_or(true, |b| ms < b.start) {
                let caps: Vec<Option<(usize, usize)>> = (0..m.len())
                    .map(|i| m.get(i).map(|g| (g.start(), g.end())))
                    .collect();
                best = Some(FoundMatch {
                    start: ms,
                    end: me,
                    ctx: ctx_id,
                    pattern: pidx,
                    pattern_index: pat_counter,
                    caps,
                    operation_kind: match pat.operation {
                        MatchOperation::Push(_) | MatchOperation::Set(_) => OpKind::PushOrSet,
                        MatchOperation::Pop(_) => OpKind::Pop,
                        MatchOperation::None => OpKind::None,
                    },
                });
                if ms == start {
                    break;
                }
            }
        }
        best
    }

    fn collect_patterns(&self, ctx_id: CtxId, set: &SyntaxSet, out: &mut Vec<(CtxId, usize)>, visited: &mut Vec<CtxId>) {
        if visited.contains(&ctx_id) {
            return;
        }
        visited.push(ctx_id);
        let ctx = set.context(ctx_id);
        for (i, p) in ctx.patterns.iter().enumerate() {
            match p {
                Pattern::Match(_) => out.push((ctx_id, i)),
                Pattern::Include(r) => {
                    if let Some(target) = set.resolve_ref(ctx_id.syntax, r) {
                        self.collect_patterns(target, set, out, visited);
                    }
                }
            }
        }
    }

    fn exec_pattern(&mut self, line: &str, m: &FoundMatch, set: &SyntaxSet, ops: &mut Vec<(usize, ScopeStackOp)>) {
        let cur_level = self.stack.last().unwrap().clone();
        let cur_ctx_id = cur_level.context;
        let ctx = set.context(m.ctx);
        let Pattern::Match(pat) = &ctx.patterns[m.pattern] else { return };
        let (ms, me) = (m.start, m.end);
        let cur_ctx = set.context(cur_ctx_id);

        // Resolve the target contexts of the operation.
        let targets: Vec<CtxId> = match &pat.operation {
            MatchOperation::Push(refs) | MatchOperation::Set(refs) => refs
                .iter()
                .filter_map(|r| set.resolve_ref(m.ctx.syntax, r))
                .collect(),
            _ => Vec::new(),
        };

        // Initial meta ops
        match &pat.operation {
            MatchOperation::Pop(_) => {
                if !cur_ctx.meta_content_scope.is_empty() {
                    ops.push((ms, ScopeStackOp::Pop(cur_ctx.meta_content_scope.len())));
                }
            }
            MatchOperation::Push(_) | MatchOperation::Set(_) => {
                if matches!(pat.operation, MatchOperation::Set(_)) && !cur_ctx.meta_content_scope.is_empty() {
                    ops.push((ms, ScopeStackOp::Pop(cur_ctx.meta_content_scope.len())));
                }
                for t in &targets {
                    let tctx = set.context(*t);
                    if let Some(clear) = tctx.clear_scopes {
                        ops.push((ms, ScopeStackOp::Clear(clear)));
                    }
                    for s in &tctx.meta_scope {
                        ops.push((ms, ScopeStackOp::Push(s.clone())));
                    }
                }
            }
            MatchOperation::None => {}
        }

        // Match scope
        for s in &pat.scope {
            ops.push((ms, ScopeStackOp::Push(s.clone())));
        }
        // Captures
        if !pat.captures.is_empty() {
            let mut map: Vec<((usize, i64), ScopeStackOp)> = Vec::new();
            for (cap_index, scopes) in &pat.captures {
                if let Some(Some((cs, ce))) = m.caps.get(*cap_index) {
                    if cs == ce {
                        continue;
                    }
                    for s in scopes {
                        map.push(((*cs, -((ce - cs) as i64)), ScopeStackOp::Push(s.clone())));
                    }
                    map.push(((*ce, i64::MIN), ScopeStackOp::Pop(scopes.len())));
                }
            }
            map.sort_by(|a, b| a.0.cmp(&b.0));
            for ((idx, _), op) in map {
                ops.push((idx, op));
            }
        }
        if !pat.scope.is_empty() {
            ops.push((me, ScopeStackOp::Pop(pat.scope.len())));
        }

        // Final meta ops
        match &pat.operation {
            MatchOperation::Pop(_) => {
                if !cur_ctx.meta_scope.is_empty() {
                    ops.push((me, ScopeStackOp::Pop(cur_ctx.meta_scope.len())));
                }
                if cur_ctx.clear_scopes.is_some() {
                    ops.push((me, ScopeStackOp::Restore));
                }
            }
            MatchOperation::Push(_) | MatchOperation::Set(_) => {
                for t in &targets {
                    let tctx = set.context(*t);
                    for s in &tctx.meta_content_scope {
                        ops.push((me, ScopeStackOp::Push(s.clone())));
                    }
                }
            }
            MatchOperation::None => {}
        }

        // Stack changes
        let captures: Option<Arc<Vec<Option<String>>>> = if targets.iter().any(|t| set.context(*t).uses_backrefs || set.syntaxes[t.syntax].contexts.iter().any(|_| false)) || !targets.is_empty() {
            Some(Arc::new(
                m.caps
                    .iter()
                    .map(|c| c.map(|(s, e)| line[s..e].to_string()))
                    .collect(),
            ))
        } else {
            None
        };
        match &pat.operation {
            MatchOperation::Pop(n) => {
                for _ in 0..*n {
                    if self.stack.len() > 1 {
                        self.stack.pop();
                    }
                }
            }
            MatchOperation::Push(_) => {
                for t in &targets {
                    let mut protos = Vec::new();
                    if let Some(p) = pat.with_prototype {
                        protos.push(CtxId { syntax: m.ctx.syntax, ctx: p });
                    }
                    self.stack.push(StateLevel {
                        context: *t,
                        prototypes: protos,
                        captures: captures.clone(),
                    });
                }
            }
            MatchOperation::Set(_) => {
                if self.stack.len() > 1 || true {
                    self.stack.pop();
                }
                for t in &targets {
                    let mut protos = Vec::new();
                    if let Some(p) = pat.with_prototype {
                        protos.push(CtxId { syntax: m.ctx.syntax, ctx: p });
                    }
                    self.stack.push(StateLevel {
                        context: *t,
                        prototypes: protos,
                        captures: captures.clone(),
                    });
                }
                if self.stack.is_empty() {
                    self.stack.push(cur_level);
                }
            }
            MatchOperation::None => {}
        }
    }
}

#[derive(Debug, Clone, Copy)]
enum OpKind {
    None,
    PushOrSet,
    Pop,
}

struct FoundMatch {
    start: usize,
    end: usize,
    ctx: CtxId,
    pattern: usize,
    pattern_index: usize,
    caps: Vec<Option<(usize, usize)>>,
    operation_kind: OpKind,
}

fn substitute_backrefs(regex_str: &str, caps: Option<&Vec<Option<String>>>) -> String {
    let b = regex_str.as_bytes();
    let mut out = String::with_capacity(regex_str.len());
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'\\' && i + 1 < b.len() {
            if b[i + 1].is_ascii_digit() && b[i + 1] != b'0' {
                let n = (b[i + 1] - b'0') as usize;
                let text = caps.and_then(|c| c.get(n).cloned().flatten()).unwrap_or_default();
                out.push_str(&fancy_regex::escape(&text));
                i += 2;
                continue;
            }
            out.push_str(&regex_str[i..i + 2]);
            i += 2;
            continue;
        }
        let ch = regex_str[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    out
}
