//! Turn scope operations into styled regions.

use std::sync::Arc;

use crate::parser::{ParseState, SyntaxSet};
use crate::syntax::{ClearAmount, ScopeStackOp};
use crate::terminal::HlStyle;
use crate::theme::{style_for_scopes, Theme};

pub trait LineHighlighter {
    fn highlight_line<'l>(&mut self, line: &'l str) -> Vec<(HlStyle, &'l str)>;
    fn is_plain_text(&self) -> bool;
}

pub struct PlainHighlighter {
    pub style: HlStyle,
}

impl LineHighlighter for PlainHighlighter {
    fn highlight_line<'l>(&mut self, line: &'l str) -> Vec<(HlStyle, &'l str)> {
        vec![(self.style, line)]
    }
    fn is_plain_text(&self) -> bool {
        true
    }
}

pub struct SyntaxHighlighter<'a> {
    set: &'a SyntaxSet,
    theme: &'a Theme,
    state: ParseState,
    scopes: Vec<Arc<str>>,
    styles: Vec<HlStyle>,
    cleared: Vec<Vec<(Arc<str>, HlStyle)>>,
    plain: bool,
    style_cache: std::collections::HashMap<Vec<Arc<str>>, HlStyle>,
}

impl<'a> SyntaxHighlighter<'a> {
    pub fn new(set: &'a SyntaxSet, syntax: usize, theme: &'a Theme) -> Self {
        let plain = set.syntaxes[syntax].name == "Plain Text";
        SyntaxHighlighter {
            set,
            theme,
            state: ParseState::new(set, syntax),
            scopes: Vec::new(),
            styles: Vec::new(),
            cleared: Vec::new(),
            plain,
            style_cache: std::collections::HashMap::new(),
        }
    }

    fn current_style(&self) -> HlStyle {
        self.styles.last().copied().unwrap_or_else(|| self.theme.default_style())
    }

    fn compute_style(&mut self) -> HlStyle {
        if let Some(s) = self.style_cache.get(&self.scopes) {
            return *s;
        }
        let refs: Vec<&str> = self.scopes.iter().map(|s| s.as_ref()).collect();
        let st = style_for_scopes(self.theme, &refs);
        self.style_cache.insert(self.scopes.clone(), st);
        st
    }

    fn apply(&mut self, op: &ScopeStackOp) {
        match op {
            ScopeStackOp::Push(s) => {
                self.scopes.push(s.clone());
                let st = self.compute_style();
                self.styles.push(st);
            }
            ScopeStackOp::Pop(n) => {
                for _ in 0..*n {
                    self.scopes.pop();
                    self.styles.pop();
                }
            }
            ScopeStackOp::Clear(amount) => {
                let n = match amount {
                    ClearAmount::TopN(n) => (*n).min(self.scopes.len()),
                    ClearAmount::All => self.scopes.len(),
                };
                let mut saved = Vec::new();
                for _ in 0..n {
                    let s = self.scopes.pop().unwrap();
                    let st = self.styles.pop().unwrap();
                    saved.push((s, st));
                }
                saved.reverse();
                self.cleared.push(saved);
            }
            ScopeStackOp::Restore => {
                if let Some(saved) = self.cleared.pop() {
                    for (s, st) in saved {
                        self.scopes.push(s);
                        self.styles.push(st);
                    }
                }
            }
            ScopeStackOp::Noop => {}
        }
    }
}

impl<'a> LineHighlighter for SyntaxHighlighter<'a> {
    fn highlight_line<'l>(&mut self, line: &'l str) -> Vec<(HlStyle, &'l str)> {
        let ops = self.state.parse_line(line, self.set);
        let mut regions: Vec<(HlStyle, &'l str)> = Vec::new();
        let mut pos = 0;
        for (end, op) in &ops {
            let end = (*end).min(line.len());
            if end > pos {
                regions.push((self.current_style(), &line[pos..end]));
                pos = end;
            }
            self.apply(op);
        }
        if pos < line.len() {
            regions.push((self.current_style(), &line[pos..]));
        }
        regions
    }

    fn is_plain_text(&self) -> bool {
        self.plain
    }
}
