        if let Some(s) = self.get_extension_syntax(file_name) {
            return Some(s);
        }
        let name = file_name.to_string_lossy();
        let builtin: &[&str] = &[
            ".bak", ".dev", ".dist", ".local", ".orig", ".tmp", "~", ".in", ".old",
        ];
        let mut suffixes: Vec<&str> = builtin.to_vec();
        for s in mapping.ignored_suffixes() {
            suffixes.push(s);
        }
        for suffix in suffixes {
            if let Some(stripped) = name.strip_suffix(suffix) {
