        };

        match result {
            Some(s) => Ok(s),
            None => {
                if let Some(fallback) = &config.fallback_syntax {
                    if let Some(s) = self.find_syntax_by_token(fallback) {
                        return Ok(s);
                    }
                }
                Ok(self.plain_text())
            }
        }
    }

    pub fn highlighter<'a>(&'a self, syntax: SyntaxRef, theme: &'a Theme) -> Box<dyn LineHighlighter + 'a> {
        match syntax.index {
            Some(idx) => Box::new(SyntaxHighlighter::new(self.syntax_set(), idx, theme)),
            None => Box::new(PlainHighlighter {
                style: theme.default_style(),
            }),
        }
    }

    pub fn highlighter_for_name<'a>(&'a self, name: &str, theme: &'a Theme) -> Box<dyn LineHighlighter + 'a> {
        self.highlighter(self.make_ref(name), theme)
    }
}
