use std::env;
use std::ffi::OsString;
use std::io::{self, Write};
use std::process::{Child, Command, Stdio};

use crate::config::{PagingMode, WrappingMode};
use crate::error::*;

#[derive(Debug, PartialEq, Eq)]
enum PagerSource {
    Config,
    EnvVarBatPager,
    EnvVarPager,
    Default,
}

#[derive(Debug, PartialEq, Eq)]
enum PagerKind {
    Bat,
    Less,
    More,
    Most,
    Other,
}

impl PagerKind {
    fn from_bin(bin: &str) -> PagerKind {
        use std::path::Path;
        match Path::new(bin).file_stem().map(|s| s.to_string_lossy()).as_deref() {
            Some("bat") => PagerKind::Bat,
            Some("less") => PagerKind::Less,
            Some("more") => PagerKind::More,
            Some("most") => PagerKind::Most,
            _ => PagerKind::Other,
        }
    }
}

struct Pager {
    bin: String,
    args: Vec<String>,
    kind: PagerKind,
    source: PagerSource,
}

fn get_pager(config_pager: Option<&str>) -> Result<Option<Pager>> {
    let bat_pager = env::var("BAT_PAGER");
    let pager = env::var("PAGER");

    let (cmd, source) = match (config_pager, &bat_pager, &pager) {
        (Some(config_pager), _, _) => (config_pager, PagerSource::Config),
        (_, Ok(bat_pager), _) => (bat_pager.as_str(), PagerSource::EnvVarBatPager),
        (_, _, Ok(pager)) => (pager.as_str(), PagerSource::EnvVarPager),
        _ => ("less", PagerSource::Default),
    };

    let parts = crate::config_file::shell_words::split(cmd).map_err(|_| Error::Msg("Could not parse pager command.".into()))?;

    match parts.split_first() {
        Some((bin, args)) => {
            let kind = PagerKind::from_bin(bin);

            let use_less_instead = source == PagerSource::EnvVarPager && kind == PagerKind::More || kind == PagerKind::Most;
            let use_less_instead = use_less_instead && source == PagerSource::EnvVarPager;

            Ok(Some(if use_less_instead {
                Pager {
                    bin: "less".to_string(),
                    args: Vec::new(),
