//! Helpers for `--list-themes`, `--help` highlighting and `--diagnostic`.

use std::io::Write;

use crate::app::App;
use crate::assets::HighlightingAssets;
use crate::config::Config;
use crate::controller::Controller;
use crate::error::*;
use crate::input::Input;

pub const THEME_PREVIEW: &str = "  // Output the square of a number.\n  fn print_square(num: f64) {\n      let result = f64::powf(num, 2.0);\n      println!(\"The square of {num:.2} is {result:.2}.\");\n  }\n";

pub fn print_theme_preview(config: &Config, assets: &HighlightingAssets, out: &mut dyn Write) -> Result<()> {
    let input = Input::from_bytes(THEME_PREVIEW.as_bytes().to_vec(), "theme-preview.rs");
    let controller = Controller::new(config, assets);
    controller.run(vec![input], out)?;
