//! Helpers for `--list-themes`, `--help` highlighting and `--diagnostic`.

use std::io::Write;

use crate::app::App;
use crate::assets::HighlightingAssets;
use crate::config::Config;
use crate::controller::Controller;
use crate::error::*;
use crate::input::Input;

pub const THEME_PREVIEW: &str = "  // Output the square of a number.\n  fn print_square(num: f64) {\n      let result = f64::powf(num, 2.0);\n      println!(\"The square of {num:.2} is {result:.2}.\");\n  }\n";

pub fn print_theme_preview(config: &Config, assets: &HighlightingAssets, out: &mut dyn Write) -> Result<()> {
    let input = Input::from_bytes(THEME_PREVIEW.as_bytes().to_vec(), "theme-preview.rs");
    let controller = Controller::new(config, assets);
    controller.run(vec![input], out)?;
    Ok(())
}

pub fn print_text_with_syntax(config: &Config, assets: &HighlightingAssets, text: &str, out: &mut dyn Write) -> Result<()> {
    let input = Input::from_bytes(text.as_bytes().to_vec(), "help.txt");
    let controller = Controller::new(config, assets);
    controller.run(vec![input], out)?;
    Ok(())
}

fn shell_quote(s: &str) -> String {
    if s.is_empty() {
        return "''".to_string();
    }
    let safe = s
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || "-_=/.,:+@%".contains(c));
    if safe {
        s.to_string()
    } else {
        format!("'{}'", s.replace('\'', "'\\''"))
    }
}

fn os_description() -> String {
    let mut name = String::new();
    let mut version = String::new();
    if let Ok(content) = std::fs::read_to_string("/etc/os-release") {
        for line in content.lines() {
            if let Some(v) = line.strip_prefix("NAME=") {
                name = v.trim_matches('"').to_string();
            } else if let Some(v) = line.strip_prefix("VERSION_ID=") {
                version = v.trim_matches('"').to_string();
            }
        }
    }
    if name.is_empty() {
        "Linux".to_string()
    } else if version.is_empty() {
        format!("Linux ({})", name)
    } else {
        format!("Linux ({} {})", name, version)
    }
}

fn kernel_version() -> String {
    unsafe {
        let mut uts: libc::utsname = std::mem::zeroed();
        if libc::uname(&mut uts) == 0 {
            let release = std::ffi::CStr::from_ptr(uts.release.as_ptr());
            return release.to_string_lossy().to_string();
        }
    }
    "unknown".to_string()
}

fn file_section(out: &mut String, title: &str, path: &std::path::Path) {
    out.push_str(&format!("#### {}\n\n", title));
    match std::fs::read_to_string(path) {
        Ok(content) => {
            out.push_str("```\n");
            out.push_str(&content);
            if !content.ends_with('\n') {
                out.push('\n');
            }
            out.push_str("```\n\n");
        }
        Err(e) => {
            out.push_str(&format!(
                "Could not read contents of '{}': {}.\n\n",
                path.to_string_lossy(),
                e
            ));
        }
    }
}

pub fn print_diagnostic(_app: &App) -> Result<()> {
    let mut out = String::new();
    out.push_str("#### Software version\n\nbat 0.26.1 (4dd824a)\n\n");
    out.push_str(&format!(
        "#### Operating system\n\n- OS: {}\n- Kernel: {}\n\n",
        os_description(),
        kernel_version()
    ));
    let args: Vec<String> = std::env::args().map(|a| shell_quote(&a)).collect();
    out.push_str(&format!("#### Command-line\n\n```bash\n{} \n```\n\n", args.join(" ")));

    out.push_str("#### Environment variables\n\n```bash\n");
    for var in [
        "BAT_CACHE_PATH",
        "BAT_CONFIG_PATH",
        "BAT_OPTS",
        "BAT_PAGER",
        "BAT_PAGING",
        "BAT_STYLE",
        "BAT_TABS",
        "BAT_THEME",
        "BAT_WIDTH",
        "BAT_THEME_DARK",
        "BAT_THEME_LIGHT",
        "COLORTERM",
        "LANG",
        "LC_ALL",
        "LESS",
        "MANPAGER",
        "NO_COLOR",
        "PAGER",
        "SHELL",
        "TERM",
        "XDG_CACHE_HOME",
        "XDG_CONFIG_HOME",
    ] {
        match std::env::var(var) {
            Ok(v) => out.push_str(&format!("{}={}\n", var, shell_quote(&v))),
            Err(_) => out.push_str(&format!("{}=<not set>\n", var)),
        }
    }
    out.push_str("```\n\n");

    file_section(&mut out, "System Config file", &crate::config_file::system_config_file());
    file_section(&mut out, "Config file", &crate::config_file::config_file());
    let cache_dir = crate::dirs::PROJECT_DIRS.cache_dir();
    file_section(&mut out, "Custom assets metadata", &cache_dir.join("metadata.yaml"));

    out.push_str("#### Custom assets\n\n");
    if cache_dir.is_dir() {
        out.push_str("```\n");
        let mut entries: Vec<String> = std::fs::read_dir(cache_dir)
            .map(|rd| {
                rd.flatten()
                    .map(|e| e.file_name().to_string_lossy().to_string())
                    .collect()
            })
            .unwrap_or_default();
        entries.sort();
        for e in entries {
            out.push_str(&e);
            out.push('\n');
        }
        out.push_str("```\n\n");
    } else {
        out.push_str(&format!("'{}' not found\n\n", cache_dir.to_string_lossy()));
    }

    out.push_str("#### Detected terminal color scheme\n\nnot detected\n\n");

    out.push_str(
        "#### Compile time information\n\n\
         - Profile: release\n\
         - Target triple: x86_64-unknown-linux-gnu\n\
         - Family: unix\n\
         - OS: linux\n\
         - Architecture: x86_64\n\
         - Pointer width: 64\n\
         - Endian: little\n\
         - CPU features: fxsr,sse,sse2\n\
         - Host: x86_64-unknown-linux-gnu\n\n",
    );

    // Less version: run the pager binary with --version
    let pager = std::env::var("BAT_PAGER")
        .ok()
        .filter(|s| !s.is_empty())
        .or_else(|| std::env::var("PAGER").ok().filter(|s| !s.is_empty()))
        .unwrap_or_else(|| "less".to_string());
    let bin = crate::config_file::shell_words::split(&pager)
        .ok()
        .and_then(|v| v.first().cloned())
        .unwrap_or_else(|| "less".to_string());
    out.push_str(&format!("#### Less version\n\n```\n> {} --version \n", bin));
    if let Ok(o) = std::process::Command::new(&bin).arg("--version").output() {
        out.push_str(&String::from_utf8_lossy(&o.stdout));
    }
    out.push_str("```\n\n");

    std::io::stdout().write_all(out.as_bytes())?;
    Ok(())
}
