#!/usr/bin/env python3
"""Probe the real bat for the style of given scope stacks under all themes.
Input: file with one stack per line: "base.scope sub.scope1 sub.scope2 ..."
Output: JSON {theme: {stack: style}} where style = {fg:[r,g,b,a] or null, bg:..., font:int}
"""
import subprocess, os, sys, re, json, collections
THEMES = subprocess.run(['./mybat','--list-themes'],capture_output=True).stdout.decode().split('\n')
THEMES = [t for t in THEMES if t]

def build_probe(stacks, workdir):
    os.makedirs(workdir + '/syntaxes', exist_ok=True)
    for f in os.listdir(workdir + '/syntaxes'): os.remove(workdir + '/syntaxes/' + f)
    by_base = collections.OrderedDict()
    for st in stacks:
        parts = st.split()
        by_base.setdefault(parts[0], []).append(parts[1:])
    files = {}
    for bi, (base, subs) in enumerate(by_base.items()):
        name = 'Probe%d' % bi
        y = ['%YAML 1.2', '---', 'name: ' + name, 'file_extensions: [probe%d]' % bi, 'scope: ' + base, 'contexts:', '  main:']
        for i, sub in enumerate(subs):
            y.append("    - match: '\\bt%d\\b'" % i)
            if sub:
                y.append("      scope: " + ' '.join(sub))
        open('%s/syntaxes/%s.sublime-syntax' % (workdir, name), 'w').write('\n'.join(y) + '\n')
        text = ' '.join('t%d' % i for i in range(len(subs))) + '\n'
        files[base] = ('%s/f%d.probe%d' % (workdir, bi, bi), subs)
        open(files[base][0], 'w').write(text)
    r = subprocess.run(['./mybat','cache','--build','--source',workdir,'--target',workdir+'/cache'], capture_output=True)
    return files

TOK = re.compile(r'\x1b\[([0-9;]*)m')
def parse_sgr(params):
    style = {'fg': None, 'bg': None, 'font': 0}
    p = params.split(';') if params else ['0']
    i = 0
    while i < len(p):
        c = p[i]
        if c == '1': style['font'] |= 1
        elif c == '4': style['font'] |= 2
        elif c == '3': style['font'] |= 4
        elif c in ('30','31','32','33','34','35','36','37'):
            style['fg'] = [int(c)-30, 0, 0, 0]
        elif c in ('40','41','42','43','44','45','46','47'):
            style['bg'] = [int(c)-40, 0, 0, 0]
        elif c in ('38','48'):
            kind = p[i+1]
            if kind == '5':
                col = [int(p[i+2]), 0, 0, 0]; i += 2
            else:
                col = [int(p[i+2]), int(p[i+3]), int(p[i+4]), 255]; i += 4
            style['fg' if c == '38' else 'bg'] = col
        i += 1
    return style

def probe(stacks, workdir='probe_theme'):
    files = build_probe(stacks, workdir)
    results = {}
    env = dict(os.environ); env['BAT_CACHE_PATH'] = workdir + '/cache'; env['COLORTERM'] = 'truecolor'
    for theme in THEMES:
        results[theme] = {}
        for base, (fname, subs) in files.items():
            out = subprocess.run(['./mybat', '--theme=' + theme, '-f', '-p', '--italic-text=always', fname], env=env, capture_output=True).stdout.decode()
            # tokenize: sequence of (style, text)
            toks = []
            pos = 0
            cur = None
            for m in TOK.finditer(out):
                if m.start() > pos:
                    toks.append((cur, out[pos:m.start()]))
                params = m.group(1)
                if params == '0': cur = None
                else: cur = parse_sgr(params)
                pos = m.end()
            if pos < len(out): toks.append((cur, out[pos:]))
            # map tokens tN -> style
            found = {}
            for st, txt in toks:
                for word in re.findall(r't\d+', txt):
                    if txt.strip() == word or word == txt:
                        found[word] = st
                    elif word not in found:
                        found[word] = st
            for i, sub in enumerate(subs):
                key = ' '.join([base] + sub)
                st = found.get('t%d' % i)
                if st is None: st = {'fg': None, 'bg': None, 'font': 0}
                results[theme][key] = st
    return results

if __name__ == '__main__':
    stacks = [l.strip() for l in open(sys.argv[1]) if l.strip()]
    res = probe(stacks)
    json.dump(res, open(sys.argv[2], 'w'), indent=0)
    print('probed', len(stacks), 'stacks for', len(THEMES), 'themes')
