TOK = re.compile(r'\x1b\[([0-9;]*)m')
def tokens(out):
    res = []
    for line in out.split('\n'):
        toks = []
        pos = 0; cur = ''
        for m in TOK.finditer(line):
            if m.start() > pos: toks.append((cur, line[pos:m.start()]))
            cur = '' if m.group(1) == '0' else m.group(1)
            pos = m.end()
        if pos < len(line): toks.append((cur, line[pos:]))
        res.append(toks)
    return res
def run(binary, args):
    env = dict(os.environ); env['COLORTERM'] = 'truecolor'
    return subprocess.run([binary, '-f', '-p', '--italic-text=always'] + args, env=env, capture_output=True).stdout.decode('utf-8', 'replace')
if __name__ == '__main__':
    args = sys.argv[1:]
    maxdiff = 5
    if args and args[0].startswith('-n'):
        maxdiff = int(args[0][2:]); args = args[1:]
    ref = tokens(run('/tmp/t/mybat', args))
    mine = tokens(run('/workspace/target/debug/bat', args))
    ndiff = 0
    for i, (a, b) in enumerate(zip(ref, mine)):
        if a != b:
            ndiff += 1
            if ndiff <= maxdiff:
                print('--- line %d differs' % (i+1))
                print('  REF :', a)
                print('  MINE:', b)
    if len(ref) != len(mine):
        print('line count differs', len(ref), len(mine))
    print('total differing lines: %d / %d' % (ndiff, len(ref)))
